import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, orderBy, limit } from "firebase/firestore";
import "../../styles/department/IssueQueue.css";

const PRIORITY_LEVELS = {
  low: { label: 'Low', color: '#28a745', icon: '🟢' },
  medium: { label: 'Medium', color: '#ffc107', icon: '🟡' },
  high: { label: 'High', color: '#fd7e14', icon: '🟠' },
  critical: { label: 'Critical', color: '#dc3545', icon: '🔴' }
};

const STATUS_LEVELS = {
  pending: { label: 'Pending', color: '#ffc107', icon: '⏳' },
  validated: { label: 'Validated', color: '#17a2b8', icon: '✅' },
  'in-progress': { label: 'In Progress', color: '#007bff', icon: '🔄' },
  resolved: { label: 'Resolved', color: '#28a745', icon: '✅' },
  rejected: { label: 'Rejected', color: '#dc3545', icon: '❌' }
};

export default function IssueQueue({ department, onStatsUpdate }) {
  const [issues, setIssues] = useState([]);
  const [filteredIssues, setFilteredIssues] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    status: 'all',
    priority: 'all',
    category: 'all',
    sortBy: 'createdAt',
    sortOrder: 'desc'
  });
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchIssues();
  }, [department]);

  useEffect(() => {
    applyFilters();
  }, [issues, filters, searchTerm]);

  const fetchIssues = async () => {
    try {
      setLoading(true);
      
      // Fetch issues for this department
      const issuesQuery = query(
        collection(db, "reports"),
        where("department", "==", department),
        orderBy("createdAt", "desc"),
        limit(100)
      );
      
      const issuesSnapshot = await getDocs(issuesQuery);
      const issuesData = issuesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setIssues(issuesData);
    } catch (error) {
      console.error("Error fetching issues:", error);
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...issues];

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(issue =>
        issue.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        issue.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        issue.location?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (filters.status !== 'all') {
      filtered = filtered.filter(issue => issue.status === filters.status);
    }

    // Priority filter
    if (filters.priority !== 'all') {
      filtered = filtered.filter(issue => issue.priority === filters.priority);
    }

    // Category filter
    if (filters.category !== 'all') {
      filtered = filtered.filter(issue => issue.category === filters.category);
    }

    // Sorting
    filtered.sort((a, b) => {
      let aValue = a[filters.sortBy];
      let bValue = b[filters.sortBy];

      if (filters.sortBy === 'createdAt') {
        aValue = new Date(aValue);
        bValue = new Date(bValue);
      }

      if (filters.sortOrder === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue < bValue ? 1 : -1;
      }
    });

    setFilteredIssues(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const getPriorityInfo = (priority) => {
    return PRIORITY_LEVELS[priority] || PRIORITY_LEVELS.medium;
  };

  const getStatusInfo = (status) => {
    return STATUS_LEVELS[status] || STATUS_LEVELS.pending;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getUniqueCategories = () => {
    const categories = [...new Set(issues.map(issue => issue.category))];
    return categories.filter(Boolean);
  };

  if (loading) {
    return (
      <div className="issue-queue-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading issues...</p>
      </div>
    );
  }

  return (
    <div className="issue-queue">
      <div className="issue-queue-header">
        <h2>📋 Issue Queue</h2>
        <p>Manage incoming issues for {department} department</p>
      </div>

      {/* Filters and Search */}
      <div className="issue-queue-controls">
        <div className="search-bar">
          <input
            type="text"
            placeholder="Search issues by title, description, or location..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
          <span className="search-icon">🔍</span>
        </div>

        <div className="filters">
          <select
            value={filters.status}
            onChange={(e) => handleFilterChange('status', e.target.value)}
            className="filter-select"
          >
            <option value="all">All Status</option>
            {Object.entries(STATUS_LEVELS).map(([key, info]) => (
              <option key={key} value={key}>{info.icon} {info.label}</option>
            ))}
          </select>

          <select
            value={filters.priority}
            onChange={(e) => handleFilterChange('priority', e.target.value)}
            className="filter-select"
          >
            <option value="all">All Priority</option>
            {Object.entries(PRIORITY_LEVELS).map(([key, info]) => (
              <option key={key} value={key}>{info.icon} {info.label}</option>
            ))}
          </select>

          <select
            value={filters.category}
            onChange={(e) => handleFilterChange('category', e.target.value)}
            className="filter-select"
          >
            <option value="all">All Categories</option>
            {getUniqueCategories().map(category => (
              <option key={category} value={category}>{category}</option>
            ))}
          </select>

          <select
            value={`${filters.sortBy}-${filters.sortOrder}`}
            onChange={(e) => {
              const [sortBy, sortOrder] = e.target.value.split('-');
              setFilters(prev => ({ ...prev, sortBy, sortOrder }));
            }}
            className="filter-select"
          >
            <option value="createdAt-desc">Newest First</option>
            <option value="createdAt-asc">Oldest First</option>
            <option value="priority-desc">Priority High to Low</option>
            <option value="priority-asc">Priority Low to High</option>
            <option value="title-asc">Title A-Z</option>
            <option value="title-desc">Title Z-A</option>
          </select>
        </div>
      </div>

      {/* Issues List */}
      <div className="issues-list">
        {filteredIssues.length === 0 ? (
          <div className="no-issues">
            <div className="no-issues-icon">📭</div>
            <h3>No issues found</h3>
            <p>No issues match your current filters.</p>
          </div>
        ) : (
          filteredIssues.map(issue => (
            <div key={issue.id} className="issue-card">
              <div className="issue-header">
                <div className="issue-title">
                  <h3>{issue.title}</h3>
                  <span className="issue-id">#{issue.id.slice(-8)}</span>
                </div>
                <div className="issue-badges">
                  <span 
                    className="priority-badge"
                    style={{ backgroundColor: getPriorityInfo(issue.priority).color }}
                  >
                    {getPriorityInfo(issue.priority).icon} {getPriorityInfo(issue.priority).label}
                  </span>
                  <span 
                    className="status-badge"
                    style={{ backgroundColor: getStatusInfo(issue.status).color }}
                  >
                    {getStatusInfo(issue.status).icon} {getStatusInfo(issue.status).label}
                  </span>
                </div>
              </div>

              <div className="issue-content">
                <p className="issue-description">{issue.description}</p>
                
                <div className="issue-details">
                  <div className="issue-detail">
                    <span className="detail-label">📍 Location:</span>
                    <span className="detail-value">{issue.location}</span>
                  </div>
                  <div className="issue-detail">
                    <span className="detail-label">📂 Category:</span>
                    <span className="detail-value">{issue.category}</span>
                  </div>
                  <div className="issue-detail">
                    <span className="detail-label">👤 Reporter:</span>
                    <span className="detail-value">{issue.reporterEmail}</span>
                  </div>
                  <div className="issue-detail">
                    <span className="detail-label">📅 Reported:</span>
                    <span className="detail-value">{formatDate(issue.createdAt)}</span>
                  </div>
                </div>

                {issue.images && issue.images.length > 0 && (
                  <div className="issue-images">
                    <span className="images-label">📷 Images:</span>
                    <div className="images-count">{issue.images.length} image(s)</div>
                  </div>
                )}
              </div>

              <div className="issue-actions">
                <button className="action-btn primary">View Details</button>
                <button className="action-btn secondary">Validate</button>
                <button className="action-btn secondary">Assign</button>
                <button className="action-btn secondary">Update Status</button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Summary */}
      <div className="issues-summary">
        <p>Showing {filteredIssues.length} of {issues.length} issues</p>
      </div>
    </div>
  );
}
