import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs } from "firebase/firestore";
import "../../styles/department/AnalyticsDashboard.css";

export default function AnalyticsDashboard({ department }) {
  const [analytics, setAnalytics] = useState({
    totalIssues: 0,
    resolvedIssues: 0,
    pendingIssues: 0,
    rejectedIssues: 0,
    avgResolutionTime: 0,
    resolutionRate: 0,
    categoryBreakdown: {},
    priorityBreakdown: {},
    monthlyTrends: [],
    locationHeatmap: []
  });
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState('30days');

  useEffect(() => {
    fetchAnalytics();
  }, [department, timeRange]);

  const fetchAnalytics = async () => {
    try {
      setLoading(true);
      
      const issuesQuery = query(
        collection(db, "reports"),
        where("department", "==", department)
      );
      
      const issuesSnapshot = await getDocs(issuesQuery);
      const issues = issuesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      // Calculate analytics
      const totalIssues = issues.length;
      const resolvedIssues = issues.filter(issue => issue.status === 'resolved').length;
      const pendingIssues = issues.filter(issue => issue.status === 'pending').length;
      const rejectedIssues = issues.filter(issue => issue.status === 'rejected').length;
      
      const resolutionRate = totalIssues > 0 ? (resolvedIssues / totalIssues) * 100 : 0;

      // Calculate average resolution time
      const resolvedIssuesWithTime = issues.filter(issue => 
        issue.status === 'resolved' && issue.resolvedAt && issue.createdAt
      );
      
      const avgResolutionTime = resolvedIssuesWithTime.length > 0 
        ? resolvedIssuesWithTime.reduce((sum, issue) => {
            const created = new Date(issue.createdAt);
            const resolved = new Date(issue.resolvedAt);
            return sum + (resolved - created) / (1000 * 60 * 60 * 24); // days
          }, 0) / resolvedIssuesWithTime.length
        : 0;

      // Category breakdown
      const categoryBreakdown = issues.reduce((acc, issue) => {
        acc[issue.category] = (acc[issue.category] || 0) + 1;
        return acc;
      }, {});

      // Priority breakdown
      const priorityBreakdown = issues.reduce((acc, issue) => {
        acc[issue.priority] = (acc[issue.priority] || 0) + 1;
        return acc;
      }, {});

      // Monthly trends (last 6 months)
      const monthlyTrends = generateMonthlyTrends(issues);

      // Location heatmap (top locations)
      const locationHeatmap = generateLocationHeatmap(issues);

      setAnalytics({
        totalIssues,
        resolvedIssues,
        pendingIssues,
        rejectedIssues,
        avgResolutionTime: Math.round(avgResolutionTime * 10) / 10,
        resolutionRate: Math.round(resolutionRate * 10) / 10,
        categoryBreakdown,
        priorityBreakdown,
        monthlyTrends,
        locationHeatmap
      });

    } catch (error) {
      console.error("Error fetching analytics:", error);
    } finally {
      setLoading(false);
    }
  };

  const generateMonthlyTrends = (issues) => {
    const months = [];
    const now = new Date();
    
    for (let i = 5; i >= 0; i--) {
      const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const monthName = date.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
      
      const monthIssues = issues.filter(issue => {
        const issueDate = new Date(issue.createdAt);
        return issueDate.getMonth() === date.getMonth() && 
               issueDate.getFullYear() === date.getFullYear();
      });

      months.push({
        month: monthName,
        total: monthIssues.length,
        resolved: monthIssues.filter(issue => issue.status === 'resolved').length,
        pending: monthIssues.filter(issue => issue.status === 'pending').length
      });
    }
    
    return months;
  };

  const generateLocationHeatmap = (issues) => {
    const locationCounts = issues.reduce((acc, issue) => {
      const location = issue.location || 'Unknown';
      acc[location] = (acc[location] || 0) + 1;
      return acc;
    }, {});

    return Object.entries(locationCounts)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10)
      .map(([location, count]) => ({ location, count }));
  };

  const getSLAStatus = (resolutionRate) => {
    if (resolutionRate >= 90) return { status: 'Excellent', color: '#28a745' };
    if (resolutionRate >= 75) return { status: 'Good', color: '#ffc107' };
    if (resolutionRate >= 60) return { status: 'Fair', color: '#fd7e14' };
    return { status: 'Poor', color: '#dc3545' };
  };

  if (loading) {
    return (
      <div className="analytics-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading analytics...</p>
      </div>
    );
  }

  const slaStatus = getSLAStatus(analytics.resolutionRate);

  return (
    <div className="analytics-dashboard">
      <div className="analytics-header">
        <h2>📊 Analytics Dashboard</h2>
        <p>Comprehensive insights and performance metrics</p>
        
        <div className="time-range-selector">
          <label htmlFor="timeRange">Time Range:</label>
          <select
            id="timeRange"
            value={timeRange}
            onChange={(e) => setTimeRange(e.target.value)}
            className="time-range-select"
          >
            <option value="7days">Last 7 days</option>
            <option value="30days">Last 30 days</option>
            <option value="90days">Last 90 days</option>
            <option value="1year">Last year</option>
          </select>
        </div>
      </div>

      <div className="analytics-content">
        {/* Key Metrics */}
        <div className="metrics-grid">
          <div className="metric-card total">
            <div className="metric-icon">📊</div>
            <div className="metric-content">
              <div className="metric-number">{analytics.totalIssues}</div>
              <div className="metric-label">Total Issues</div>
            </div>
          </div>
          
          <div className="metric-card resolved">
            <div className="metric-icon">✅</div>
            <div className="metric-content">
              <div className="metric-number">{analytics.resolvedIssues}</div>
              <div className="metric-label">Resolved</div>
            </div>
          </div>
          
          <div className="metric-card pending">
            <div className="metric-icon">⏳</div>
            <div className="metric-content">
              <div className="metric-number">{analytics.pendingIssues}</div>
              <div className="metric-label">Pending</div>
            </div>
          </div>
          
          <div className="metric-card rejected">
            <div className="metric-icon">❌</div>
            <div className="metric-content">
              <div className="metric-number">{analytics.rejectedIssues}</div>
              <div className="metric-label">Rejected</div>
            </div>
          </div>
        </div>

        {/* Performance Metrics */}
        <div className="performance-metrics">
          <div className="performance-card">
            <h3>📈 Resolution Rate</h3>
            <div className="performance-value">
              <span className="rate-number">{analytics.resolutionRate}%</span>
              <span 
                className="rate-status"
                style={{ color: slaStatus.color }}
              >
                {slaStatus.status}
              </span>
            </div>
            <div className="performance-bar">
              <div 
                className="performance-fill"
                style={{ 
                  width: `${analytics.resolutionRate}%`,
                  backgroundColor: slaStatus.color
                }}
              ></div>
            </div>
          </div>

          <div className="performance-card">
            <h3>⏱️ Average Resolution Time</h3>
            <div className="performance-value">
              <span className="time-number">{analytics.avgResolutionTime}</span>
              <span className="time-unit">days</span>
            </div>
            <div className="performance-description">
              Average time from report to resolution
            </div>
          </div>
        </div>

        {/* Charts Section */}
        <div className="charts-section">
          <div className="chart-card">
            <h3>📊 Issues by Category</h3>
            <div className="category-chart">
              {Object.entries(analytics.categoryBreakdown).map(([category, count]) => (
                <div key={category} className="category-item">
                  <div className="category-bar">
                    <div 
                      className="category-fill"
                      style={{ 
                        width: `${(count / analytics.totalIssues) * 100}%`,
                        backgroundColor: `hsl(${Math.random() * 360}, 70%, 50%)`
                      }}
                    ></div>
                  </div>
                  <div className="category-info">
                    <span className="category-name">{category}</span>
                    <span className="category-count">{count}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="chart-card">
            <h3>🎯 Issues by Priority</h3>
            <div className="priority-chart">
              {Object.entries(analytics.priorityBreakdown).map(([priority, count]) => (
                <div key={priority} className="priority-item">
                  <div className="priority-bar">
                    <div 
                      className="priority-fill"
                      style={{ 
                        width: `${(count / analytics.totalIssues) * 100}%`,
                        backgroundColor: priority === 'critical' ? '#dc3545' :
                                       priority === 'high' ? '#fd7e14' :
                                       priority === 'medium' ? '#ffc107' : '#28a745'
                      }}
                    ></div>
                  </div>
                  <div className="priority-info">
                    <span className="priority-name">{priority}</span>
                    <span className="priority-count">{count}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Monthly Trends */}
        <div className="trends-section">
          <div className="trends-card">
            <h3>📈 Monthly Trends</h3>
            <div className="trends-chart">
              {analytics.monthlyTrends.map((trend, index) => (
                <div key={index} className="trend-item">
                  <div className="trend-month">{trend.month}</div>
                  <div className="trend-bars">
                    <div className="trend-bar resolved" style={{ height: `${(trend.resolved / Math.max(...analytics.monthlyTrends.map(t => t.total))) * 100}%` }}></div>
                    <div className="trend-bar pending" style={{ height: `${(trend.pending / Math.max(...analytics.monthlyTrends.map(t => t.total))) * 100}%` }}></div>
                  </div>
                  <div className="trend-total">{trend.total}</div>
                </div>
              ))}
            </div>
            <div className="trends-legend">
              <div className="legend-item">
                <div className="legend-color resolved"></div>
                <span>Resolved</span>
              </div>
              <div className="legend-item">
                <div className="legend-color pending"></div>
                <span>Pending</span>
              </div>
            </div>
          </div>
        </div>

        {/* Location Heatmap */}
        <div className="heatmap-section">
          <div className="heatmap-card">
            <h3>🗺️ Location Heatmap</h3>
            <div className="heatmap-list">
              {analytics.locationHeatmap.map((item, index) => (
                <div key={index} className="heatmap-item">
                  <div className="heatmap-location">{item.location}</div>
                  <div className="heatmap-bar">
                    <div 
                      className="heatmap-fill"
                      style={{ 
                        width: `${(item.count / analytics.locationHeatmap[0].count) * 100}%`,
                        backgroundColor: `hsl(${120 - (index * 20)}, 70%, 50%)`
                      }}
                    ></div>
                  </div>
                  <div className="heatmap-count">{item.count}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
