import React from 'react';

const REPORT_STATUSES = {
  SUBMITTED: 'submitted',
  UNDER_REVIEW: 'under_review',
  ASSIGNED: 'assigned',
  IN_PROGRESS: 'in_progress',
  RESOLVED: 'resolved',
  CLOSED: 'closed',
  REJECTED: 'rejected'
};

const PRIORITY_LEVELS = {
  LOW: 'low',
  MEDIUM: 'medium',
  HIGH: 'high',
  CRITICAL: 'critical'
};

const CATEGORIES = {
  ROADS: 'roads_transport',
  WATER: 'water_sewage',
  ELECTRICITY: 'electricity',
  SANITATION: 'waste_management',
  SAFETY: 'public_safety',
  PARKS: 'parks_recreation',
  LIGHTING: 'street_lighting',
  OTHER: 'other'
};

const DEPARTMENTS = [
  'Public Works',
  'Water Authority',
  'Electric Board',
  'Sanitation Department',
  'Police Department',
  'Parks & Recreation',
  'Transportation'
];

export default function ReportFilters({ 
  filters, 
  setFilters, 
  sortBy, 
  setSortBy, 
  sortOrder, 
  setSortOrder 
}) {
  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const clearFilters = () => {
    setFilters({
      status: '',
      category: '',
      priority: '',
      department: '',
      dateFrom: '',
      dateTo: '',
      searchTerm: ''
    });
  };

  const getStatusLabel = (status) => {
    const labels = {
      [REPORT_STATUSES.SUBMITTED]: '📝 Submitted',
      [REPORT_STATUSES.UNDER_REVIEW]: '👀 Under Review',
      [REPORT_STATUSES.ASSIGNED]: '👥 Assigned',
      [REPORT_STATUSES.IN_PROGRESS]: '⚡ In Progress',
      [REPORT_STATUSES.RESOLVED]: '✅ Resolved',
      [REPORT_STATUSES.CLOSED]: '🔒 Closed',
      [REPORT_STATUSES.REJECTED]: '❌ Rejected'
    };
    return labels[status] || status;
  };

  const getCategoryLabel = (category) => {
    const labels = {
      [CATEGORIES.ROADS]: '🛣️ Roads & Transport',
      [CATEGORIES.WATER]: '💧 Water & Sewage',
      [CATEGORIES.ELECTRICITY]: '⚡ Electricity',
      [CATEGORIES.SANITATION]: '🗑️ Sanitation & Waste',
      [CATEGORIES.SAFETY]: '🚨 Public Safety',
      [CATEGORIES.PARKS]: '🌳 Parks & Recreation',
      [CATEGORIES.LIGHTING]: '🏮 Street Lighting',
      [CATEGORIES.OTHER]: '📝 Other Issues'
    };
    return labels[category] || category;
  };

  const getPriorityLabel = (priority) => {
    const labels = {
      [PRIORITY_LEVELS.LOW]: '🟢 Low Priority',
      [PRIORITY_LEVELS.MEDIUM]: '🟡 Medium Priority',
      [PRIORITY_LEVELS.HIGH]: '🟠 High Priority',
      [PRIORITY_LEVELS.CRITICAL]: '🔴 Critical'
    };
    return labels[priority] || priority;
  };

  return (
    <div className="report-filters">
      <div className="filters-row">
        {/* Search Bar */}
        <div className="filter-group">
          <label htmlFor="search">🔍 Search Reports</label>
          <input
            id="search"
            type="text"
            placeholder="Search by title, description, or location..."
            value={filters.searchTerm}
            onChange={(e) => handleFilterChange('searchTerm', e.target.value)}
            className="search-input"
          />
        </div>

        {/* Status Filter */}
        <div className="filter-group">
          <label htmlFor="status">Status</label>
          <select
            id="status"
            value={filters.status}
            onChange={(e) => handleFilterChange('status', e.target.value)}
          >
            <option value="">All Statuses</option>
            {Object.values(REPORT_STATUSES).map(status => (
              <option key={status} value={status}>
                {getStatusLabel(status)}
              </option>
            ))}
          </select>
        </div>

        {/* Category Filter */}
        <div className="filter-group">
          <label htmlFor="category">Category</label>
          <select
            id="category"
            value={filters.category}
            onChange={(e) => handleFilterChange('category', e.target.value)}
          >
            <option value="">All Categories</option>
            {Object.values(CATEGORIES).map(category => (
              <option key={category} value={category}>
                {getCategoryLabel(category)}
              </option>
            ))}
          </select>
        </div>

        {/* Priority Filter */}
        <div className="filter-group">
          <label htmlFor="priority">Priority</label>
          <select
            id="priority"
            value={filters.priority}
            onChange={(e) => handleFilterChange('priority', e.target.value)}
          >
            <option value="">All Priorities</option>
            {Object.values(PRIORITY_LEVELS).map(priority => (
              <option key={priority} value={priority}>
                {getPriorityLabel(priority)}
              </option>
            ))}
          </select>
        </div>

        {/* Department Filter */}
        <div className="filter-group">
          <label htmlFor="department">Department</label>
          <select
            id="department"
            value={filters.department}
            onChange={(e) => handleFilterChange('department', e.target.value)}
          >
            <option value="">All Departments</option>
            {DEPARTMENTS.map(dept => (
              <option key={dept} value={dept}>{dept}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="filters-row">
        {/* Date Range */}
        <div className="filter-group">
          <label htmlFor="dateFrom">From Date</label>
          <input
            id="dateFrom"
            type="date"
            value={filters.dateFrom}
            onChange={(e) => handleFilterChange('dateFrom', e.target.value)}
          />
        </div>

        <div className="filter-group">
          <label htmlFor="dateTo">To Date</label>
          <input
            id="dateTo"
            type="date"
            value={filters.dateTo}
            onChange={(e) => handleFilterChange('dateTo', e.target.value)}
          />
        </div>

        {/* Sort Options */}
        <div className="filter-group">
          <label htmlFor="sortBy">Sort By</label>
          <select
            id="sortBy"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
          >
            <option value="createdAt">Created Date</option>
            <option value="priority">Priority</option>
            <option value="status">Status</option>
            <option value="category">Category</option>
            <option value="votes.totalVotes">Votes</option>
            <option value="views">Views</option>
          </select>
        </div>

        <div className="filter-group">
          <label htmlFor="sortOrder">Order</label>
          <select
            id="sortOrder"
            value={sortOrder}
            onChange={(e) => setSortOrder(e.target.value)}
          >
            <option value="desc">Descending</option>
            <option value="asc">Ascending</option>
          </select>
        </div>

        {/* Clear Filters Button */}
        <div className="filter-group">
          <button 
            className="clear-filters-btn"
            onClick={clearFilters}
            type="button"
          >
            🗑️ Clear Filters
          </button>
        </div>
      </div>
    </div>
  );
}