import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, orderBy, limit } from "firebase/firestore";
import "../../styles/department/AuditTrail.css";

export default function AuditTrail({ department }) {
  const [auditLogs, setAuditLogs] = useState([]);
  const [filteredLogs, setFilteredLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    action: 'all',
    performedBy: 'all',
    dateRange: 'all'
  });
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchAuditLogs();
  }, [department]);

  useEffect(() => {
    applyFilters();
  }, [auditLogs, filters, searchTerm]);

  const fetchAuditLogs = async () => {
    try {
      setLoading(true);
      
      const auditQuery = query(
        collection(db, "auditTrail"),
        where("department", "==", department),
        orderBy("performedAt", "desc"),
        limit(200)
      );
      
      const auditSnapshot = await getDocs(auditQuery);
      const auditData = auditSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setAuditLogs(auditData);
    } catch (error) {
      console.error("Error fetching audit logs:", error);
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...auditLogs];

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(log =>
        log.action?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        log.details?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        log.performedBy?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Action filter
    if (filters.action !== 'all') {
      filtered = filtered.filter(log => log.action === filters.action);
    }

    // Performed by filter
    if (filters.performedBy !== 'all') {
      filtered = filtered.filter(log => log.performedBy === filters.performedBy);
    }

    // Date range filter
    if (filters.dateRange !== 'all') {
      const now = new Date();
      const cutoffDate = new Date();
      
      switch (filters.dateRange) {
        case 'today':
          cutoffDate.setHours(0, 0, 0, 0);
          break;
        case 'week':
          cutoffDate.setDate(now.getDate() - 7);
          break;
        case 'month':
          cutoffDate.setMonth(now.getMonth() - 1);
          break;
        case 'year':
          cutoffDate.setFullYear(now.getFullYear() - 1);
          break;
      }
      
      filtered = filtered.filter(log => new Date(log.performedAt) >= cutoffDate);
    }

    setFilteredLogs(filtered);
  };

  const getActionIcon = (action) => {
    const icons = {
      'Issue validated': '✅',
      'Issue rejected': '❌',
      'Issue Assigned': '👥',
      'Status Updated': '📝',
      'Bulk validate': '✅',
      'Bulk reject': '❌',
      'Bulk assign': '👥',
      'Bulk resolve': '✅',
      'Bulk merge': '🔗'
    };
    return icons[action] || '📋';
  };

  const getActionColor = (action) => {
    if (action.includes('validated') || action.includes('resolve')) return '#28a745';
    if (action.includes('rejected')) return '#dc3545';
    if (action.includes('Assigned') || action.includes('assign')) return '#007bff';
    if (action.includes('Status Updated') || action.includes('Updated')) return '#6f42c1';
    if (action.includes('Bulk')) return '#6c757d';
    return '#17a2b8';
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const getUniqueActions = () => {
    const actions = [...new Set(auditLogs.map(log => log.action))];
    return actions.filter(Boolean);
  };

  const getUniquePerformers = () => {
    const performers = [...new Set(auditLogs.map(log => log.performedBy))];
    return performers.filter(Boolean);
  };

  if (loading) {
    return (
      <div className="audit-trail-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading audit trail...</p>
      </div>
    );
  }

  return (
    <div className="audit-trail">
      <div className="audit-trail-header">
        <h2>📋 Audit Trail</h2>
        <p>Track all actions and changes for transparency</p>
      </div>

      <div className="audit-trail-content">
        {/* Filters */}
        <div className="audit-filters">
          <div className="search-bar">
            <input
              type="text"
              placeholder="Search audit logs..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
            <span className="search-icon">🔍</span>
          </div>

          <div className="filter-controls">
            <select
              value={filters.action}
              onChange={(e) => setFilters(prev => ({ ...prev, action: e.target.value }))}
              className="filter-select"
            >
              <option value="all">All Actions</option>
              {getUniqueActions().map(action => (
                <option key={action} value={action}>{getActionIcon(action)} {action}</option>
              ))}
            </select>

            <select
              value={filters.performedBy}
              onChange={(e) => setFilters(prev => ({ ...prev, performedBy: e.target.value }))}
              className="filter-select"
            >
              <option value="all">All Users</option>
              {getUniquePerformers().map(performer => (
                <option key={performer} value={performer}>{performer}</option>
              ))}
            </select>

            <select
              value={filters.dateRange}
              onChange={(e) => setFilters(prev => ({ ...prev, dateRange: e.target.value }))}
              className="filter-select"
            >
              <option value="all">All Time</option>
              <option value="today">Today</option>
              <option value="week">Last 7 Days</option>
              <option value="month">Last 30 Days</option>
              <option value="year">Last Year</option>
            </select>
          </div>
        </div>

        {/* Audit Logs */}
        <div className="audit-logs">
          <div className="logs-header">
            <h3>Audit Logs ({filteredLogs.length})</h3>
            <div className="logs-summary">
              <span>Total Actions: {auditLogs.length}</span>
              <span>Filtered: {filteredLogs.length}</span>
            </div>
          </div>

          {filteredLogs.length === 0 ? (
            <div className="no-logs">
              <div className="no-logs-icon">📭</div>
              <h4>No audit logs found</h4>
              <p>No logs match your current filters.</p>
            </div>
          ) : (
            <div className="logs-list">
              {filteredLogs.map(log => (
                <div key={log.id} className="audit-log-card">
                  <div className="log-header">
                    <div className="log-action">
                      <span 
                        className="action-icon"
                        style={{ backgroundColor: getActionColor(log.action) }}
                      >
                        {getActionIcon(log.action)}
                      </span>
                      <div className="action-details">
                        <h4>{log.action}</h4>
                        <span className="log-id">#{log.id.slice(-8)}</span>
                      </div>
                    </div>
                    <div className="log-timestamp">
                      {formatDate(log.performedAt)}
                    </div>
                  </div>

                  <div className="log-content">
                    <div className="log-details">
                      <p>{log.details}</p>
                    </div>

                    <div className="log-meta">
                      <div className="meta-item">
                        <span className="meta-label">Performed By:</span>
                        <span className="meta-value">{log.performedBy}</span>
                      </div>
                      <div className="meta-item">
                        <span className="meta-label">Issue ID:</span>
                        <span className="meta-value">{log.issueId}</span>
                      </div>
                      <div className="meta-item">
                        <span className="meta-label">Department:</span>
                        <span className="meta-value">{log.department}</span>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
