import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, doc, updateDoc, addDoc, writeBatch } from "firebase/firestore";
import "../../styles/department/BulkHandling.css";

export default function BulkHandling({ department, onStatsUpdate }) {
  const [issues, setIssues] = useState([]);
  const [selectedIssues, setSelectedIssues] = useState([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [bulkAction, setBulkAction] = useState('');
  const [bulkNotes, setBulkNotes] = useState('');

  useEffect(() => {
    fetchIssues();
  }, [department]);

  const fetchIssues = async () => {
    try {
      setLoading(true);
      
      const issuesQuery = query(
        collection(db, "reports"),
        where("department", "==", department)
      );
      
      const issuesSnapshot = await getDocs(issuesQuery);
      const issuesData = issuesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setIssues(issuesData);
    } catch (error) {
      console.error("Error fetching issues:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectAll = () => {
    if (selectedIssues.length === issues.length) {
      setSelectedIssues([]);
    } else {
      setSelectedIssues(issues.map(issue => issue.id));
    }
  };

  const handleSelectIssue = (issueId) => {
    setSelectedIssues(prev => 
      prev.includes(issueId) 
        ? prev.filter(id => id !== issueId)
        : [...prev, issueId]
    );
  };

  const handleBulkAction = async () => {
    if (selectedIssues.length === 0) {
      alert('Please select issues to perform bulk action');
      return;
    }

    if (!bulkAction) {
      alert('Please select a bulk action');
      return;
    }

    try {
      setProcessing(true);
      
      const batch = writeBatch(db);
      const auditPromises = [];

      for (const issueId of selectedIssues) {
        const issueRef = doc(db, "reports", issueId);
        
        let updateData = {
          bulkUpdatedAt: new Date().toISOString(),
          bulkUpdatedBy: 'department',
          bulkNotes: bulkNotes
        };

        switch (bulkAction) {
          case 'validate':
            updateData.status = 'validated';
            updateData.validatedAt = new Date().toISOString();
            break;
          case 'reject':
            updateData.status = 'rejected';
            updateData.rejectedAt = new Date().toISOString();
            break;
          case 'assign':
            updateData.status = 'in-progress';
            updateData.assignedAt = new Date().toISOString();
            break;
          case 'resolve':
            updateData.status = 'resolved';
            updateData.resolvedAt = new Date().toISOString();
            break;
          case 'merge':
            // For merge, we'll mark as merged and add reference to main issue
            updateData.status = 'merged';
            updateData.mergedAt = new Date().toISOString();
            break;
        }

        batch.update(issueRef, updateData);

        // Add to audit trail
        auditPromises.push(
          addDoc(collection(db, "auditTrail"), {
            issueId: issueId,
            action: `Bulk ${bulkAction}`,
            performedBy: 'department',
            performedAt: new Date().toISOString(),
            details: `Bulk ${bulkAction} performed on ${selectedIssues.length} issues. Notes: ${bulkNotes}`,
            department: department
          })
        );
      }

      await batch.commit();
      await Promise.all(auditPromises);

      // Refresh data
      await fetchIssues();
      if (onStatsUpdate) onStatsUpdate();
      
      setSelectedIssues([]);
      setBulkAction('');
      setBulkNotes('');
      
      alert(`Bulk ${bulkAction} completed successfully on ${selectedIssues.length} issues!`);
      
    } catch (error) {
      console.error("Error performing bulk action:", error);
      alert('Error performing bulk action. Please try again.');
    } finally {
      setProcessing(false);
    }
  };

  const getStatusColor = (status) => {
    const colors = {
      pending: '#ffc107',
      validated: '#17a2b8',
      'in-progress': '#007bff',
      resolved: '#28a745',
      rejected: '#dc3545',
      merged: '#6c757d'
    };
    return colors[status] || '#6c757d';
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="bulk-handling-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading bulk handling...</p>
      </div>
    );
  }

  return (
    <div className="bulk-handling">
      <div className="bulk-handling-header">
        <h2>📦 Bulk Handling</h2>
        <p>Perform bulk operations on multiple issues</p>
      </div>

      <div className="bulk-handling-content">
        <div className="bulk-controls">
          <div className="selection-controls">
            <div className="select-all">
              <input
                type="checkbox"
                id="selectAll"
                checked={selectedIssues.length === issues.length}
                onChange={handleSelectAll}
                className="select-checkbox"
              />
              <label htmlFor="selectAll">
                Select All ({selectedIssues.length}/{issues.length})
              </label>
            </div>
          </div>

          {selectedIssues.length > 0 && (
            <div className="bulk-actions">
              <div className="action-selection">
                <label htmlFor="bulkAction">Bulk Action:</label>
                <select
                  id="bulkAction"
                  value={bulkAction}
                  onChange={(e) => setBulkAction(e.target.value)}
                  className="action-select"
                >
                  <option value="">Choose action...</option>
                  <option value="validate">✅ Validate Selected</option>
                  <option value="reject">❌ Reject Selected</option>
                  <option value="assign">👥 Assign Selected</option>
                  <option value="resolve">✅ Resolve Selected</option>
                  <option value="merge">🔗 Merge Selected</option>
                </select>
              </div>

              <div className="action-notes">
                <label htmlFor="bulkNotes">Notes (Optional):</label>
                <textarea
                  id="bulkNotes"
                  placeholder="Add notes for this bulk action..."
                  value={bulkNotes}
                  onChange={(e) => setBulkNotes(e.target.value)}
                  className="notes-textarea"
                  rows="3"
                />
              </div>

              <button
                className="execute-btn"
                onClick={handleBulkAction}
                disabled={processing || !bulkAction}
              >
                {processing ? '🔄 Processing...' : `🚀 Execute Bulk ${bulkAction}`}
              </button>
            </div>
          )}
        </div>

        <div className="issues-table">
          <div className="table-header">
            <div className="table-cell checkbox">Select</div>
            <div className="table-cell title">Title</div>
            <div className="table-cell status">Status</div>
            <div className="table-cell priority">Priority</div>
            <div className="table-cell location">Location</div>
            <div className="table-cell date">Created</div>
          </div>

          <div className="table-body">
            {issues.length === 0 ? (
              <div className="no-issues">
                <div className="no-issues-icon">📭</div>
                <h4>No issues found</h4>
                <p>No issues available for bulk operations.</p>
              </div>
            ) : (
              issues.map(issue => (
                <div 
                  key={issue.id} 
                  className={`table-row ${selectedIssues.includes(issue.id) ? 'selected' : ''}`}
                >
                  <div className="table-cell checkbox">
                    <input
                      type="checkbox"
                      checked={selectedIssues.includes(issue.id)}
                      onChange={() => handleSelectIssue(issue.id)}
                      className="row-checkbox"
                    />
                  </div>
                  <div className="table-cell title">
                    <div className="issue-title">{issue.title}</div>
                    <div className="issue-id">#{issue.id.slice(-8)}</div>
                  </div>
                  <div className="table-cell status">
                    <span 
                      className="status-badge"
                      style={{ backgroundColor: getStatusColor(issue.status) }}
                    >
                      {issue.status}
                    </span>
                  </div>
                  <div className="table-cell priority">
                    <span className={`priority-badge ${issue.priority}`}>
                      {issue.priority}
                    </span>
                  </div>
                  <div className="table-cell location">
                    <div className="location-text">{issue.location}</div>
                  </div>
                  <div className="table-cell date">
                    <div className="date-text">{formatDate(issue.createdAt)}</div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {selectedIssues.length > 0 && (
          <div className="bulk-summary">
            <h3>Bulk Operation Summary</h3>
            <div className="summary-stats">
              <div className="stat-item">
                <span className="stat-label">Selected Issues:</span>
                <span className="stat-value">{selectedIssues.length}</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">Action:</span>
                <span className="stat-value">{bulkAction || 'None selected'}</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">Department:</span>
                <span className="stat-value">{department}</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
