import React, { useState, useEffect } from 'react';
import { auth } from '../../firebase/config.js';

// Import admin components
import ReportManagement from './reports/ReportManagement.js';
import UserManagement from './users/UserManagement.js';
import GlobalMonitoring from './monitoring/GlobalMonitoring.js';
import AIAnalytics from './analytics/AIAnalytics.js';
import WorkflowManagement from './workflow/WorkflowManagement.js';
import Gamification from './gamification/Gamification.js';
import PerformanceReports from './performance/PerformanceReports.js';
import SystemMonitoring from './system/SystemMonitoring.js';
import Configuration from './configuration/Configuration.js';

// Import styles
import '../../styles/admin/AdminStyles.css';

const ADMIN_SECTIONS = {
  OVERVIEW: 'overview',
  REPORTS: 'reports',
  USERS: 'users',
  MONITORING: 'monitoring',
  ANALYTICS: 'analytics',
  WORKFLOW: 'workflow',
  GAMIFICATION: 'gamification',
  PERFORMANCE: 'performance',
  SYSTEM: 'system',
  CONFIGURATION: 'configuration'
};

export default function AdminDashboard() {
  const [activeSection, setActiveSection] = useState(ADMIN_SECTIONS.OVERVIEW);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const navigationItems = [
    {
      id: ADMIN_SECTIONS.OVERVIEW,
      label: '📊 Dashboard Overview',
      icon: '📊',
      description: 'System overview and key metrics'
    },
    {
      id: ADMIN_SECTIONS.REPORTS,
      label: '📋 Report Management',
      icon: '📋',
      description: 'Manage citizen reports and issues'
    },
    {
      id: ADMIN_SECTIONS.USERS,
      label: '👥 User Management',
      icon: '👥',
      description: 'Manage citizens and staff accounts'
    },
    {
      id: ADMIN_SECTIONS.MONITORING,
      label: '🗺️ Global Monitoring',
      icon: '🗺️',
      description: 'Interactive maps and insights'
    },
    {
      id: ADMIN_SECTIONS.ANALYTICS,
      label: '🤖 AI Analytics',
      icon: '🤖',
      description: 'AI-powered analytics and predictions'
    },
    {
      id: ADMIN_SECTIONS.WORKFLOW,
      label: '⚡ Workflow & Escalation',
      icon: '⚡',
      description: 'Automated routing and escalation'
    },
    {
      id: ADMIN_SECTIONS.GAMIFICATION,
      label: '🏆 Community Engagement',
      icon: '🏆',
      description: 'Gamification and leaderboards'
    },
    {
      id: ADMIN_SECTIONS.PERFORMANCE,
      label: '📈 Performance Reports',
      icon: '📈',
      description: 'Analytics and policy reports'
    },
    {
      id: ADMIN_SECTIONS.SYSTEM,
      label: '⚙️ System Monitoring',
      icon: '⚙️',
      description: 'Server health and reliability'
    },
    {
      id: ADMIN_SECTIONS.CONFIGURATION,
      label: '🔧 Configuration',
      icon: '🔧',
      description: 'System settings and governance'
    }
  ];

  const renderActiveSection = () => {
    switch (activeSection) {
      case ADMIN_SECTIONS.OVERVIEW:
        return <DashboardOverview />;
      case ADMIN_SECTIONS.REPORTS:
        return <ReportManagement />;
      case ADMIN_SECTIONS.USERS:
        return <UserManagement />;
      case ADMIN_SECTIONS.MONITORING:
        return <GlobalMonitoring />;
      case ADMIN_SECTIONS.ANALYTICS:
        return <AIAnalytics />;
      case ADMIN_SECTIONS.WORKFLOW:
        return <WorkflowManagement />;
      case ADMIN_SECTIONS.GAMIFICATION:
        return <Gamification />;
      case ADMIN_SECTIONS.PERFORMANCE:
        return <PerformanceReports />;
      case ADMIN_SECTIONS.SYSTEM:
        return <SystemMonitoring />;
      case ADMIN_SECTIONS.CONFIGURATION:
        return <Configuration />;
      default:
        return <DashboardOverview />;
    }
  };

  const getActiveNavItem = () => {
    return navigationItems.find(item => item.id === activeSection);
  };

  return (
    <div className="admin-dashboard">
      <nav className="admin-nav">
        <div className="admin-nav-header">
          <h1 className="admin-title">⚙️ Urban Assistant Admin</h1>
          <div className="admin-user-info">
            <span>👤 {auth.currentUser?.email}</span>
          </div>
        </div>
        
        <div className="admin-nav-menu">
          {navigationItems.map(item => (
            <button
              key={item.id}
              className={`nav-item ${activeSection === item.id ? 'active' : ''}`}
              onClick={() => setActiveSection(item.id)}
              title={item.description}
            >
              <span className="nav-icon">{item.icon}</span>
              <span className="nav-label">{item.label.split(' ').slice(1).join(' ')}</span>
            </button>
          ))}
        </div>
      </nav>

      <main className="admin-content">
        {renderActiveSection()}
      </main>
    </div>
  );
}

// Dashboard Overview Component
function DashboardOverview() {
  const [stats, setStats] = useState({
    totalReports: 0,
    pendingReports: 0,
    resolvedReports: 0,
    totalUsers: 0,
    activeUsers: 0,
    systemHealth: 'Good'
  });

  useEffect(() => {
    // Mock data - in real implementation, fetch from Firebase/API
    setStats({
      totalReports: 1247,
      pendingReports: 89,
      resolvedReports: 1031,
      totalUsers: 5643,
      activeUsers: 892,
      systemHealth: 'Good'
    });
  }, []);

  return (
    <div className="dashboard-overview">
      <div className="overview-header">
        <h2>📊 System Overview</h2>
        <p>Welcome to the Urban Assistant Admin Dashboard. Here's a quick overview of system status.</p>
      </div>

      <div className="overview-stats">
        <div className="stats-grid">
          <div className="stat-card-large">
            <div className="stat-icon">📋</div>
            <div className="stat-info">
              <div className="stat-number">{stats.totalReports}</div>
              <div className="stat-label">Total Reports</div>
              <div className="stat-change">+12% from last month</div>
            </div>
          </div>

          <div className="stat-card-large">
            <div className="stat-icon">⏰</div>
            <div className="stat-info">
              <div className="stat-number">{stats.pendingReports}</div>
              <div className="stat-label">Pending Review</div>
              <div className="stat-change">-8% from yesterday</div>
            </div>
          </div>

          <div className="stat-card-large">
            <div className="stat-icon">✅</div>
            <div className="stat-info">
              <div className="stat-number">{stats.resolvedReports}</div>
              <div className="stat-label">Resolved Issues</div>
              <div className="stat-change">+15% this week</div>
            </div>
          </div>

          <div className="stat-card-large">
            <div className="stat-icon">👥</div>
            <div className="stat-info">
              <div className="stat-number">{stats.totalUsers}</div>
              <div className="stat-label">Total Users</div>
              <div className="stat-change">+7% growth</div>
            </div>
          </div>

          <div className="stat-card-large">
            <div className="stat-icon">🟢</div>
            <div className="stat-info">
              <div className="stat-number">{stats.activeUsers}</div>
              <div className="stat-label">Active Today</div>
              <div className="stat-change">Peak: 1,203</div>
            </div>
          </div>

          <div className="stat-card-large">
            <div className="stat-icon">⚡</div>
            <div className="stat-info">
              <div className="stat-number">{stats.systemHealth}</div>
              <div className="stat-label">System Health</div>
              <div className="stat-change">99.9% uptime</div>
            </div>
          </div>
        </div>
      </div>

      <div className="quick-actions">
        <h3>Quick Actions</h3>
        <div className="actions-grid">
          <button className="action-card" onClick={() => window.location.hash = '#reports'}>
            <div className="action-icon">📋</div>
            <div className="action-label">Review Pending Reports</div>
            <div className="action-count">{stats.pendingReports} pending</div>
          </button>
          
          <button className="action-card" onClick={() => window.location.hash = '#users'}>
            <div className="action-icon">👥</div>
            <div className="action-label">Manage Users</div>
            <div className="action-count">{stats.totalUsers} users</div>
          </button>
          
          <button className="action-card" onClick={() => window.location.hash = '#monitoring'}>
            <div className="action-icon">🗺️</div>
            <div className="action-label">View Live Map</div>
            <div className="action-count">Real-time data</div>
          </button>
          
          <button className="action-card" onClick={() => window.location.hash = '#analytics'}>
            <div className="action-icon">🤖</div>
            <div className="action-label">AI Insights</div>
            <div className="action-count">Latest analysis</div>
          </button>
        </div>
      </div>

      <div className="recent-activity">
        <h3>Recent System Activity</h3>
        <div className="activity-list">
          <div className="activity-item">
            <div className="activity-icon">📝</div>
            <div className="activity-content">
              <div className="activity-title">New report submitted</div>
              <div className="activity-details">Road pothole reported on Main Street</div>
              <div className="activity-time">2 minutes ago</div>
            </div>
          </div>
          
          <div className="activity-item">
            <div className="activity-icon">✅</div>
            <div className="activity-content">
              <div className="activity-title">Report resolved</div>
              <div className="activity-details">Street lighting fixed in Park Avenue</div>
              <div className="activity-time">15 minutes ago</div>
            </div>
          </div>
          
          <div className="activity-item">
            <div className="activity-icon">👤</div>
            <div className="activity-content">
              <div className="activity-title">New staff member added</div>
              <div className="activity-details">John Smith joined Public Works department</div>
              <div className="activity-time">1 hour ago</div>
            </div>
          </div>
          
          <div className="activity-item">
            <div className="activity-icon">🏆</div>
            <div className="activity-content">
              <div className="activity-title">Citizen achievement</div>
              <div className="activity-details">Sarah Johnson reached 50 verified reports</div>
              <div className="activity-time">3 hours ago</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}