import React, { useState } from 'react';

export default function UserCard({ user, onAction, onViewDetails }) {
  const [showActions, setShowActions] = useState(false);

  const formatDate = (date) => {
    if (!date) return 'N/A';
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const getStatusColor = (status) => {
    const colors = {
      'active': '#10b981',
      'suspended': '#f59e0b',
      'banned': '#ef4444',
      'pending': '#6b7280'
    };
    return colors[status] || '#6b7280';
  };

  const getStatusIcon = (status) => {
    const icons = {
      'active': '✅',
      'suspended': '⏸️',
      'banned': '🚫',
      'pending': '⏳'
    };
    return icons[status] || '❓';
  };

  const getTrustScoreColor = (score) => {
    if (score >= 80) return '#10b981';
    if (score >= 60) return '#f59e0b';
    if (score >= 40) return '#f97316';
    return '#ef4444';
  };

  const handleAction = (action, reason = '') => {
    if (action === 'suspend' || action === 'ban') {
      const actionReason = prompt(`Please provide a reason for ${action}ing this user:`);
      if (actionReason) {
        onAction(user.id, action, { reason: actionReason, status: action === 'suspend' ? 'suspended' : 'banned' });
      }
    } else {
      onAction(user.id, action);
    }
    setShowActions(false);
  };

  return (
    <div className="user-card" onMouseLeave={() => setShowActions(false)}>
      <div className="user-card-header">
        <div className="user-avatar">
          {user.photoURL ? (
            <img src={user.photoURL} alt={user.displayName} />
          ) : (
            <div className="avatar-placeholder">
              {(user.displayName || user.email || 'U').charAt(0).toUpperCase()}
            </div>
          )}
        </div>
        
        <div className="user-basic-info">
          <h3 className="user-name">{user.displayName || 'Unknown User'}</h3>
          <p className="user-email">{user.email}</p>
        </div>

        <div className="user-actions">
          <button 
            className="actions-toggle"
            onClick={() => setShowActions(!showActions)}
          >
            ⋯
          </button>
          {showActions && (
            <div className="actions-dropdown">
              <button onClick={() => onViewDetails(user)}>
                👁️ View Details
              </button>
              {user.status === 'active' && (
                <>
                  <button onClick={() => handleAction('suspend')}>
                    ⏸️ Suspend
                  </button>
                  <button onClick={() => handleAction('ban')}>
                    🚫 Ban
                  </button>
                </>
              )}
              {(user.status === 'suspended' || user.status === 'banned') && (
                <button onClick={() => handleAction('unban')}>
                  ✅ Restore
                </button>
              )}
              <button onClick={() => handleAction('delete')} className="danger">
                🗑️ Delete
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="user-stats">
        <div className="stat-item">
          <span className="stat-label">Trust Score</span>
          <span 
            className="stat-value trust-score"
            style={{ color: getTrustScoreColor(user.trustScore || 100) }}
          >
            {user.trustScore || 100}
          </span>
        </div>
        
        <div className="stat-item">
          <span className="stat-label">Reports</span>
          <span className="stat-value">{user.reportsSubmitted || 0}</span>
        </div>
        
        <div className="stat-item">
          <span className="stat-label">Joined</span>
          <span className="stat-value">{formatDate(user.createdAt)}</span>
        </div>
      </div>

      <div className="user-status">
        <span 
          className="status-badge"
          style={{ backgroundColor: getStatusColor(user.status || 'active') }}
        >
          {getStatusIcon(user.status || 'active')} {(user.status || 'active').toUpperCase()}
        </span>
      </div>

      {user.lastActive && (
        <div className="last-active">
          Last active: {formatDate(user.lastActive)}
        </div>
      )}

      {(user.suspensionReason || user.banReason) && (
        <div className="action-reason">
          <strong>Reason:</strong> {user.suspensionReason || user.banReason}
        </div>
      )}
    </div>
  );
}