import React from 'react';

export default function UserDetailsModal({ user, onClose, onAction }) {
  if (!user) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="user-details-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>User Details</h2>
          <button className="close-btn" onClick={onClose}>✕</button>
        </div>
        
        <div className="modal-content">
          <div className="user-info-section">
            <h3>{user.displayName || 'Unknown User'}</h3>
            <p>Email: {user.email}</p>
            <p>Status: {user.status || 'active'}</p>
            <p>Trust Score: {user.trustScore || 100}</p>
            <p>Reports Submitted: {user.reportsSubmitted || 0}</p>
            {user.department && <p>Department: {user.department}</p>}
          </div>
        </div>
        
        <div className="modal-actions">
          <button onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}