import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, doc, updateDoc, addDoc } from "firebase/firestore";
import "../../styles/department/NotificationsPanel.css";

export default function NotificationsPanel({ department }) {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [sendingNotification, setSendingNotification] = useState(false);
  const [newNotification, setNewNotification] = useState({
    type: 'status_update',
    title: '',
    message: '',
    recipients: 'all',
    priority: 'medium'
  });

  useEffect(() => {
    fetchNotifications();
  }, [department]);

  const fetchNotifications = async () => {
    try {
      setLoading(true);
      
      const notificationsQuery = query(
        collection(db, "notifications"),
        where("department", "==", department)
      );
      
      const notificationsSnapshot = await getDocs(notificationsQuery);
      const notificationsData = notificationsSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setNotifications(notificationsData.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)));
    } catch (error) {
      console.error("Error fetching notifications:", error);
    } finally {
      setLoading(false);
    }
  };

  const sendNotification = async () => {
    if (!newNotification.title || !newNotification.message) {
      alert('Please fill in title and message');
      return;
    }

    try {
      setSendingNotification(true);
      
      await addDoc(collection(db, "notifications"), {
        ...newNotification,
        department: department,
        createdAt: new Date().toISOString(),
        sentBy: 'department',
        status: 'sent',
        sentCount: 0 // In real implementation, this would be the actual count
      });

      // Reset form
      setNewNotification({
        type: 'status_update',
        title: '',
        message: '',
        recipients: 'all',
        priority: 'medium'
      });

      // Refresh notifications
      await fetchNotifications();
      
      alert('Notification sent successfully!');
      
    } catch (error) {
      console.error("Error sending notification:", error);
      alert('Error sending notification. Please try again.');
    } finally {
      setSendingNotification(false);
    }
  };

  const getNotificationIcon = (type) => {
    const icons = {
      status_update: '📝',
      resolution: '✅',
      assignment: '👥',
      general: '📢',
      urgent: '🚨'
    };
    return icons[type] || '📢';
  };

  const getPriorityColor = (priority) => {
    const colors = {
      low: '#28a745',
      medium: '#ffc107',
      high: '#fd7e14',
      urgent: '#dc3545'
    };
    return colors[priority] || '#ffc107';
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="notifications-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading notifications...</p>
      </div>
    );
  }

  return (
    <div className="notifications-panel">
      <div className="notifications-header">
        <h2>🔔 Notifications</h2>
        <p>Manage citizen notifications and communications</p>
      </div>

      <div className="notifications-content">
        <div className="notification-form">
          <h3>Send New Notification</h3>
          
          <div className="form-group">
            <label htmlFor="type">Notification Type</label>
            <select
              id="type"
              value={newNotification.type}
              onChange={(e) => setNewNotification(prev => ({ ...prev, type: e.target.value }))}
              className="form-select"
            >
              <option value="status_update">📝 Status Update</option>
              <option value="resolution">✅ Resolution</option>
              <option value="assignment">👥 Assignment</option>
              <option value="general">📢 General Announcement</option>
              <option value="urgent">🚨 Urgent Notice</option>
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="priority">Priority</label>
            <select
              id="priority"
              value={newNotification.priority}
              onChange={(e) => setNewNotification(prev => ({ ...prev, priority: e.target.value }))}
              className="form-select"
            >
              <option value="low">🟢 Low</option>
              <option value="medium">🟡 Medium</option>
              <option value="high">🟠 High</option>
              <option value="urgent">🔴 Urgent</option>
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="recipients">Recipients</label>
            <select
              id="recipients"
              value={newNotification.recipients}
              onChange={(e) => setNewNotification(prev => ({ ...prev, recipients: e.target.value }))}
              className="form-select"
            >
              <option value="all">All Citizens</option>
              <option value="affected_area">Affected Area Only</option>
              <option value="specific_users">Specific Users</option>
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="title">Title</label>
            <input
              id="title"
              type="text"
              placeholder="Enter notification title..."
              value={newNotification.title}
              onChange={(e) => setNewNotification(prev => ({ ...prev, title: e.target.value }))}
              className="form-input"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="message">Message</label>
            <textarea
              id="message"
              placeholder="Enter notification message..."
              value={newNotification.message}
              onChange={(e) => setNewNotification(prev => ({ ...prev, message: e.target.value }))}
              className="form-textarea"
              rows="4"
              required
            />
          </div>

          <button
            className="send-btn"
            onClick={sendNotification}
            disabled={sendingNotification}
          >
            {sendingNotification ? '🔄 Sending...' : '📤 Send Notification'}
          </button>
        </div>

        <div className="notifications-list">
          <h3>Recent Notifications ({notifications.length})</h3>
          
          {notifications.length === 0 ? (
            <div className="no-notifications">
              <div className="no-notifications-icon">📭</div>
              <h4>No notifications sent</h4>
              <p>No notifications have been sent yet.</p>
            </div>
          ) : (
            <div className="notifications-grid">
              {notifications.map(notification => (
                <div key={notification.id} className="notification-card">
                  <div className="notification-header">
                    <div className="notification-icon">
                      {getNotificationIcon(notification.type)}
                    </div>
                    <div className="notification-title">
                      <h4>{notification.title}</h4>
                      <span 
                        className="priority-badge"
                        style={{ backgroundColor: getPriorityColor(notification.priority) }}
                      >
                        {notification.priority}
                      </span>
                    </div>
                  </div>
                  
                  <div className="notification-content">
                    <p>{notification.message}</p>
                  </div>
                  
                  <div className="notification-meta">
                    <div className="meta-item">
                      <span className="meta-label">Type:</span>
                      <span className="meta-value">{notification.type.replace('_', ' ')}</span>
                    </div>
                    <div className="meta-item">
                      <span className="meta-label">Recipients:</span>
                      <span className="meta-value">{notification.recipients}</span>
                    </div>
                    <div className="meta-item">
                      <span className="meta-label">Sent:</span>
                      <span className="meta-value">{formatDate(notification.createdAt)}</span>
                    </div>
                    <div className="meta-item">
                      <span className="meta-label">Status:</span>
                      <span className={`meta-value status-${notification.status}`}>
                        {notification.status}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
