import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, doc, updateDoc, addDoc } from "firebase/firestore";
import "../../styles/department/AssignmentPanel.css";

export default function AssignmentPanel({ department, onStatsUpdate }) {
  const [validatedIssues, setValidatedIssues] = useState([]);
  const [fieldOfficers, setFieldOfficers] = useState([]);
  const [contractors, setContractors] = useState([]);
  const [selectedIssue, setSelectedIssue] = useState(null);
  const [assignmentType, setAssignmentType] = useState('officer');
  const [selectedAssignee, setSelectedAssignee] = useState('');
  const [assignmentNotes, setAssignmentNotes] = useState('');
  const [loading, setLoading] = useState(true);
  const [assigning, setAssigning] = useState(false);

  useEffect(() => {
    fetchData();
  }, [department]);

  const fetchData = async () => {
    try {
      setLoading(true);
      
      // Fetch validated issues
      const issuesQuery = query(
        collection(db, "reports"),
        where("department", "==", department),
        where("status", "==", "validated")
      );
      
      const issuesSnapshot = await getDocs(issuesQuery);
      const issuesData = issuesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setValidatedIssues(issuesData);

      // Mock field officers data (in real implementation, this would come from a database)
      const mockOfficers = [
        { id: 'officer1', name: 'Rajesh Kumar', email: 'rajesh.kumar@department.gov.in', phone: '+91-9876543210', specialization: 'Road Maintenance', status: 'available' },
        { id: 'officer2', name: 'Priya Sharma', email: 'priya.sharma@department.gov.in', phone: '+91-9876543211', specialization: 'Traffic Management', status: 'available' },
        { id: 'officer3', name: 'Amit Singh', email: 'amit.singh@department.gov.in', phone: '+91-9876543212', specialization: 'Infrastructure', status: 'busy' },
        { id: 'officer4', name: 'Sunita Patel', email: 'sunita.patel@department.gov.in', phone: '+91-9876543213', specialization: 'Public Safety', status: 'available' }
      ];

      // Mock contractors data
      const mockContractors = [
        { id: 'contractor1', name: 'ABC Construction Ltd.', contact: 'Mr. Ravi Verma', phone: '+91-9876543220', email: 'ravi@abcconstruction.com', specialization: 'Road Construction', rating: 4.5 },
        { id: 'contractor2', name: 'XYZ Infrastructure', contact: 'Ms. Kavita Reddy', phone: '+91-9876543221', email: 'kavita@xyzinfra.com', specialization: 'Maintenance', rating: 4.2 },
        { id: 'contractor3', name: 'DEF Engineering', contact: 'Mr. Suresh Kumar', phone: '+91-9876543222', email: 'suresh@defengg.com', specialization: 'Electrical Work', rating: 4.8 },
        { id: 'contractor4', name: 'GHI Services', contact: 'Mr. Vikram Singh', phone: '+91-9876543223', email: 'vikram@ghiservices.com', specialization: 'Sanitation', rating: 4.0 }
      ];

      setFieldOfficers(mockOfficers);
      setContractors(mockContractors);

    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAssignment = async () => {
    if (!selectedIssue || !selectedAssignee) {
      alert('Please select an issue and assignee');
      return;
    }

    try {
      setAssigning(true);
      
      const issueRef = doc(db, "reports", selectedIssue.id);
      
      await updateDoc(issueRef, {
        status: 'in-progress',
        assignedTo: selectedAssignee,
        assignedType: assignmentType,
        assignedAt: new Date().toISOString(),
        assignedBy: 'department',
        assignmentNotes: assignmentNotes
      });

      // Add to audit trail
      await addDoc(collection(db, "auditTrail"), {
        issueId: selectedIssue.id,
        action: 'Issue Assigned',
        performedBy: 'department',
        performedAt: new Date().toISOString(),
        details: `Assigned to ${assignmentType}: ${selectedAssignee}. Notes: ${assignmentNotes}`,
        department: department
      });

      // Refresh data
      await fetchData();
      if (onStatsUpdate) onStatsUpdate();
      
      setSelectedIssue(null);
      setSelectedAssignee('');
      setAssignmentNotes('');
      
      alert('Issue assigned successfully!');
      
    } catch (error) {
      console.error("Error assigning issue:", error);
      alert('Error assigning issue. Please try again.');
    } finally {
      setAssigning(false);
    }
  };

  const getAssigneeOptions = () => {
    if (assignmentType === 'officer') {
      return fieldOfficers.filter(officer => officer.status === 'available');
    } else {
      return contractors;
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="assignment-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading assignment panel...</p>
      </div>
    );
  }

  return (
    <div className="assignment-panel">
      <div className="assignment-header">
        <h2>👥 Task Assignment</h2>
        <p>Assign validated issues to field officers or contractors</p>
      </div>

      <div className="assignment-content">
        <div className="validated-issues">
          <h3>Validated Issues ({validatedIssues.length})</h3>
          
          {validatedIssues.length === 0 ? (
            <div className="no-issues">
              <div className="no-issues-icon">📋</div>
              <h4>No validated issues</h4>
              <p>No issues available for assignment.</p>
            </div>
          ) : (
            <div className="issues-list">
              {validatedIssues.map(issue => (
                <div 
                  key={issue.id} 
                  className={`issue-card ${selectedIssue?.id === issue.id ? 'selected' : ''}`}
                  onClick={() => setSelectedIssue(issue)}
                >
                  <div className="issue-header">
                    <h4>{issue.title}</h4>
                    <span className={`priority-badge ${issue.priority}`}>
                      {issue.priority}
                    </span>
                  </div>
                  <p className="issue-description">{issue.description}</p>
                  <div className="issue-meta">
                    <span>📍 {issue.location}</span>
                    <span>📅 {formatDate(issue.createdAt)}</span>
                  </div>
                  {issue.images && issue.images.length > 0 && (
                    <div className="issue-images">
                      📷 {issue.images.length} image(s)
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {selectedIssue && (
          <div className="assignment-details">
            <div className="assignment-details-header">
              <h3>Assignment Details</h3>
              <button 
                className="close-btn"
                onClick={() => {
                  setSelectedIssue(null);
                  setSelectedAssignee('');
                  setAssignmentNotes('');
                }}
              >
                ✕
              </button>
            </div>

            <div className="issue-details">
              <h4>{selectedIssue.title}</h4>
              <p>{selectedIssue.description}</p>
              
              <div className="issue-info">
                <div className="info-item">
                  <span className="label">Location:</span>
                  <span className="value">{selectedIssue.location}</span>
                </div>
                <div className="info-item">
                  <span className="label">Category:</span>
                  <span className="value">{selectedIssue.category}</span>
                </div>
                <div className="info-item">
                  <span className="label">Priority:</span>
                  <span className={`value priority-${selectedIssue.priority}`}>
                    {selectedIssue.priority}
                  </span>
                </div>
                <div className="info-item">
                  <span className="label">Validated:</span>
                  <span className="value">{formatDate(selectedIssue.validatedAt)}</span>
                </div>
              </div>
            </div>

            <div className="assignment-form">
              <h4>Assignment Options</h4>
              
              <div className="assignment-type">
                <label>
                  <input
                    type="radio"
                    name="assignmentType"
                    value="officer"
                    checked={assignmentType === 'officer'}
                    onChange={(e) => {
                      setAssignmentType(e.target.value);
                      setSelectedAssignee('');
                    }}
                  />
                  Field Officer
                </label>
                <label>
                  <input
                    type="radio"
                    name="assignmentType"
                    value="contractor"
                    checked={assignmentType === 'contractor'}
                    onChange={(e) => {
                      setAssignmentType(e.target.value);
                      setSelectedAssignee('');
                    }}
                  />
                  Contractor
                </label>
              </div>

              <div className="assignee-selection">
                <label htmlFor="assignee">Select {assignmentType === 'officer' ? 'Field Officer' : 'Contractor'}</label>
                <select
                  id="assignee"
                  value={selectedAssignee}
                  onChange={(e) => setSelectedAssignee(e.target.value)}
                  className="assignee-select"
                >
                  <option value="">Choose an option...</option>
                  {getAssigneeOptions().map(assignee => (
                    <option key={assignee.id} value={assignee.id}>
                      {assignee.name} - {assignee.specialization}
                      {assignmentType === 'contractor' && ` (Rating: ${assignee.rating})`}
                    </option>
                  ))}
                </select>
              </div>

              {selectedAssignee && (
                <div className="assignee-details">
                  {assignmentType === 'officer' ? (
                    <>
                      {fieldOfficers.find(o => o.id === selectedAssignee) && (
                        <div className="officer-info">
                          <h5>Officer Details:</h5>
                          <div className="detail-item">
                            <span>Name:</span> {fieldOfficers.find(o => o.id === selectedAssignee).name}
                          </div>
                          <div className="detail-item">
                            <span>Email:</span> {fieldOfficers.find(o => o.id === selectedAssignee).email}
                          </div>
                          <div className="detail-item">
                            <span>Phone:</span> {fieldOfficers.find(o => o.id === selectedAssignee).phone}
                          </div>
                          <div className="detail-item">
                            <span>Specialization:</span> {fieldOfficers.find(o => o.id === selectedAssignee).specialization}
                          </div>
                        </div>
                      )}
                    </>
                  ) : (
                    <>
                      {contractors.find(c => c.id === selectedAssignee) && (
                        <div className="contractor-info">
                          <h5>Contractor Details:</h5>
                          <div className="detail-item">
                            <span>Company:</span> {contractors.find(c => c.id === selectedAssignee).name}
                          </div>
                          <div className="detail-item">
                            <span>Contact:</span> {contractors.find(c => c.id === selectedAssignee).contact}
                          </div>
                          <div className="detail-item">
                            <span>Phone:</span> {contractors.find(c => c.id === selectedAssignee).phone}
                          </div>
                          <div className="detail-item">
                            <span>Email:</span> {contractors.find(c => c.id === selectedAssignee).email}
                          </div>
                          <div className="detail-item">
                            <span>Specialization:</span> {contractors.find(c => c.id === selectedAssignee).specialization}
                          </div>
                          <div className="detail-item">
                            <span>Rating:</span> ⭐ {contractors.find(c => c.id === selectedAssignee).rating}/5
                          </div>
                        </div>
                      )}
                    </>
                  )}
                </div>
              )}

              <div className="assignment-notes">
                <label htmlFor="notes">Assignment Notes (Optional)</label>
                <textarea
                  id="notes"
                  placeholder="Add any specific instructions or notes for the assignee..."
                  value={assignmentNotes}
                  onChange={(e) => setAssignmentNotes(e.target.value)}
                  className="notes-textarea"
                  rows="4"
                />
              </div>

              <div className="assignment-actions">
                <button 
                  className="assign-btn"
                  onClick={handleAssignment}
                  disabled={assigning || !selectedAssignee}
                >
                  {assigning ? '🔄 Assigning...' : '✅ Assign Issue'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
