import React, { useState, useEffect } from 'react';
import { db } from '../../../firebase/config.js';
import { collection, getDocs, query, where } from 'firebase/firestore';

const DEPARTMENTS = [
  {
    id: 'public_works',
    name: 'Public Works',
    icon: '🏗️',
    categories: ['roads_transport', 'street_lighting', 'other']
  },
  {
    id: 'water_authority',
    name: 'Water Authority',
    icon: '💧',
    categories: ['water_sewage']
  },
  {
    id: 'electric_board',
    name: 'Electric Board',
    icon: '⚡',
    categories: ['electricity']
  },
  {
    id: 'sanitation_dept',
    name: 'Sanitation Department',
    icon: '🗑️',
    categories: ['waste_management']
  },
  {
    id: 'police_dept',
    name: 'Police Department',
    icon: '🚨',
    categories: ['public_safety']
  },
  {
    id: 'parks_recreation',
    name: 'Parks & Recreation',
    icon: '🌳',
    categories: ['parks_recreation']
  }
];

export default function AssignmentModal({ report, onClose, onAssign }) {
  const [selectedDepartment, setSelectedDepartment] = useState('');
  const [selectedStaff, setSelectedStaff] = useState('');
  const [availableStaff, setAvailableStaff] = useState([]);
  const [loading, setLoading] = useState(false);
  const [assignmentNotes, setAssignmentNotes] = useState('');

  // Get recommended department based on report category
  const getRecommendedDepartment = () => {
    return DEPARTMENTS.find(dept => 
      dept.categories.includes(report.category)
    )?.id || '';
  };

  useEffect(() => {
    // Set recommended department by default
    const recommended = getRecommendedDepartment();
    setSelectedDepartment(recommended);
  }, [report.category]);

  // Fetch staff members when department is selected
  useEffect(() => {
    const fetchStaff = async () => {
      if (!selectedDepartment) {
        setAvailableStaff([]);
        return;
      }

      setLoading(true);
      try {
        // In a real application, you'd fetch from a staff collection
        // For now, we'll simulate with mock data
        const mockStaff = [
          {
            id: 'staff_1',
            name: 'John Smith',
            email: 'j.smith@dept.gov',
            role: 'Senior Officer',
            workload: 3,
            department: selectedDepartment
          },
          {
            id: 'staff_2',
            name: 'Sarah Johnson',
            email: 's.johnson@dept.gov',
            role: 'Field Inspector',
            workload: 1,
            department: selectedDepartment
          },
          {
            id: 'staff_3',
            name: 'Mike Davis',
            email: 'm.davis@dept.gov',
            role: 'Maintenance Lead',
            workload: 5,
            department: selectedDepartment
          }
        ];

        // Sort by workload (ascending) to show least busy first
        mockStaff.sort((a, b) => a.workload - b.workload);
        setAvailableStaff(mockStaff);
      } catch (error) {
        console.error('Error fetching staff:', error);
        setAvailableStaff([]);
      }
      setLoading(false);
    };

    fetchStaff();
  }, [selectedDepartment]);

  const handleAssign = () => {
    if (!selectedDepartment) {
      alert('Please select a department');
      return;
    }

    const departmentName = DEPARTMENTS.find(d => d.id === selectedDepartment)?.name;
    const staffName = availableStaff.find(s => s.id === selectedStaff)?.name;

    onAssign(report.id, departmentName, staffName);
  };

  const getDepartmentIcon = (deptId) => {
    return DEPARTMENTS.find(d => d.id === deptId)?.icon || '🏛️';
  };

  const getWorkloadColor = (workload) => {
    if (workload <= 2) return '#10b981'; // Green - Low
    if (workload <= 4) return '#f59e0b'; // Orange - Medium
    return '#ef4444'; // Red - High
  };

  const getWorkloadLabel = (workload) => {
    if (workload <= 2) return 'Low';
    if (workload <= 4) return 'Medium';
    return 'High';
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="assignment-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Assign Report</h2>
          <button className="close-btn" onClick={onClose}>✕</button>
        </div>

        <div className="modal-content">
          <div className="report-summary">
            <h3>Report: {report.title}</h3>
            <p>Category: {report.category.replace('_', ' ')}</p>
            <p>Priority: {report.priority}</p>
            <p>Location: {report.address?.city}, {report.address?.state}</p>
          </div>

          <div className="assignment-form">
            <div className="department-selection">
              <h4>Select Department:</h4>
              <div className="department-grid">
                {DEPARTMENTS.map(dept => (
                  <div 
                    key={dept.id}
                    className={`department-card ${selectedDepartment === dept.id ? 'selected' : ''} ${
                      dept.categories.includes(report.category) ? 'recommended' : ''
                    }`}
                    onClick={() => {
                      setSelectedDepartment(dept.id);
                      setSelectedStaff(''); // Reset staff selection
                    }}
                  >
                    <div className="dept-icon">{dept.icon}</div>
                    <div className="dept-name">{dept.name}</div>
                    {dept.categories.includes(report.category) && (
                      <div className="recommended-badge">Recommended</div>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {selectedDepartment && (
              <div className="staff-selection">
                <h4>
                  {getDepartmentIcon(selectedDepartment)} Available Staff - {
                    DEPARTMENTS.find(d => d.id === selectedDepartment)?.name
                  }:
                </h4>
                
                {loading ? (
                  <div className="loading">Loading staff...</div>
                ) : availableStaff.length === 0 ? (
                  <div className="no-staff">
                    <p>No available staff found for this department.</p>
                    <button 
                      className="assign-dept-only"
                      onClick={() => handleAssign()}
                    >
                      Assign to Department Only
                    </button>
                  </div>
                ) : (
                  <div className="staff-list">
                    <div 
                      className={`staff-item ${selectedStaff === '' ? 'selected' : ''}`}
                      onClick={() => setSelectedStaff('')}
                    >
                      <div className="staff-info">
                        <div className="staff-name">Department Pool (No specific assignment)</div>
                        <div className="staff-role">Any available staff member</div>
                      </div>
                    </div>
                    
                    {availableStaff.map(staff => (
                      <div 
                        key={staff.id}
                        className={`staff-item ${selectedStaff === staff.id ? 'selected' : ''}`}
                        onClick={() => setSelectedStaff(staff.id)}
                      >
                        <div className="staff-info">
                          <div className="staff-name">{staff.name}</div>
                          <div className="staff-role">{staff.role}</div>
                          <div className="staff-email">{staff.email}</div>
                        </div>
                        <div className="staff-workload">
                          <span 
                            className="workload-indicator"
                            style={{ backgroundColor: getWorkloadColor(staff.workload) }}
                          >
                            {staff.workload}
                          </span>
                          <span className="workload-label">
                            {getWorkloadLabel(staff.workload)} Load
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="assignment-notes">
              <h4>Assignment Notes (Optional):</h4>
              <textarea
                value={assignmentNotes}
                onChange={(e) => setAssignmentNotes(e.target.value)}
                placeholder="Add any special instructions or notes for the assigned department/staff..."
                rows={3}
              />
            </div>
          </div>
        </div>

        <div className="modal-actions">
          <button className="cancel-btn" onClick={onClose}>
            Cancel
          </button>
          <button 
            className="assign-btn"
            onClick={handleAssign}
            disabled={!selectedDepartment}
          >
            {selectedStaff ? 
              `Assign to ${availableStaff.find(s => s.id === selectedStaff)?.name}` :
              `Assign to ${DEPARTMENTS.find(d => d.id === selectedDepartment)?.name}`
            }
          </button>
        </div>
      </div>
    </div>
  );
}