import React, { useState } from "react";
import { auth, db } from "../../firebase/config.js";
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from "firebase/auth";
import { doc, setDoc, getDoc } from "firebase/firestore";
import "../../styles/department/DepartmentLogin.css";

const DEPARTMENTS = {
  ROADS: {
    id: 'roads',
    name: 'Roads',
    fullName: 'National Highways Authority of India (NHAI) / Public Works Department',
    icon: '🛣️'
  },
  SANITATION: {
    id: 'sanitation',
    name: 'Sanitation',
    fullName: 'Municipal Corporation / Municipality',
    icon: '🗑️'
  },
  ELECTRICITY: {
    id: 'electricity',
    name: 'Electricity',
    fullName: 'TNEB',
    icon: '⚡'
  }
};

export default function DepartmentLogin() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [selectedDepartment, setSelectedDepartment] = useState(DEPARTMENTS.ROADS.id);
  const [isLogin, setIsLogin] = useState(true);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAuth = async () => {
    if (!email || !password || !selectedDepartment) {
      setMessage("⚠️ Please fill in all fields");
      return;
    }

    setLoading(true);
    setMessage("");

    try {
      let userCredential;
      
      if (isLogin) {
        userCredential = await signInWithEmailAndPassword(auth, email, password);
        
        // Verify user department
        const userDoc = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();
          if (userData.role !== 'department' || userData.department !== selectedDepartment) {
            setMessage("❌ Invalid department selection for this account");
            await auth.signOut();
            setLoading(false);
            return;
          }
        }
        
        setMessage("✅ Logged in successfully!");
      } else {
        userCredential = await createUserWithEmailAndPassword(auth, email, password);
        
        // Store user role and department data
        await setDoc(doc(db, "users", userCredential.user.uid), {
          email: email,
          role: 'department',
          department: selectedDepartment,
          departmentName: DEPARTMENTS[selectedDepartment.toUpperCase()].fullName,
          trustScore: 100,
          reportsHandled: 0,
          createdAt: new Date().toISOString(),
          isActive: true,
          permissions: {
            canValidate: true,
            canAssign: true,
            canUpdateStatus: true,
            canExport: true
          }
        });
        
        setMessage("✅ Department account created successfully!");
      }
    } catch (error) {
      setMessage(`❌ ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="department-login-container">
      <div className="department-login-card">
        <div className="department-login-header">
          <h1>🏛️ Department Portal</h1>
          <h2>{isLogin ? "Department Sign In" : "Department Registration"}</h2>
          <p>{isLogin ? "Access your department dashboard" : "Create department account"}</p>
        </div>

        <form className="department-login-form" onSubmit={(e) => e.preventDefault()}>
          <div className="form-group">
            <label htmlFor="department">Select Department</label>
            <select 
              id="department"
              className="form-select"
              value={selectedDepartment} 
              onChange={(e) => setSelectedDepartment(e.target.value)}
            >
              <option value={DEPARTMENTS.ROADS.id}>
                {DEPARTMENTS.ROADS.icon} {DEPARTMENTS.ROADS.name} - {DEPARTMENTS.ROADS.fullName}
              </option>
              <option value={DEPARTMENTS.SANITATION.id}>
                {DEPARTMENTS.SANITATION.icon} {DEPARTMENTS.SANITATION.name} - {DEPARTMENTS.SANITATION.fullName}
              </option>
              <option value={DEPARTMENTS.ELECTRICITY.id}>
                {DEPARTMENTS.ELECTRICITY.icon} {DEPARTMENTS.ELECTRICITY.name} - {DEPARTMENTS.ELECTRICITY.fullName}
              </option>
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="email">Email Address</label>
            <input
              id="email"
              className="form-input"
              type="email"
              placeholder="Enter your department email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              id="password"
              className="form-input"
              type="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button
            className={`department-login-btn ${loading ? 'loading' : ''}`}
            onClick={handleAuth}
            disabled={loading}
          >
            {loading ? (
              <span>🔄 Processing...</span>
            ) : (
              <span>{isLogin ? "Sign In" : "Create Account"}</span>
            )}
          </button>

          <div className="department-login-switch">
            <p>
              {isLogin ? "Don't have a department account? " : "Already have a department account? "}
              <button 
                type="button"
                className="switch-btn"
                onClick={() => setIsLogin(!isLogin)}
              >
                {isLogin ? "Register" : "Sign In"}
              </button>
            </p>
          </div>

          {message && (
            <div className={`message ${message.includes('✅') ? 'success' : 'error'}`}>
              {message}
            </div>
          )}
        </form>
      </div>
    </div>
  );
}
