import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, doc, updateDoc, addDoc } from "firebase/firestore";
import "../../styles/department/StatusUpdates.css";

const STATUS_OPTIONS = [
  { value: 'validated', label: 'Validated', icon: '✅', color: '#17a2b8' },
  { value: 'in-progress', label: 'In Progress', icon: '🔄', color: '#007bff' },
  { value: 'resolved', label: 'Resolved', icon: '✅', color: '#28a745' },
  { value: 'rejected', label: 'Rejected', icon: '❌', color: '#dc3545' },
  { value: 'on-hold', label: 'On Hold', icon: '⏸️', color: '#6c757d' }
];

export default function StatusUpdates({ department, onStatsUpdate }) {
  const [issues, setIssues] = useState([]);
  const [selectedIssue, setSelectedIssue] = useState(null);
  const [newStatus, setNewStatus] = useState('');
  const [statusNotes, setStatusNotes] = useState('');
  const [loading, setLoading] = useState(true);
  const [updating, setUpdating] = useState(false);

  useEffect(() => {
    fetchIssues();
  }, [department]);

  const fetchIssues = async () => {
    try {
      setLoading(true);
      
      const issuesQuery = query(
        collection(db, "reports"),
        where("department", "==", department),
        where("status", "in", ["validated", "in-progress", "on-hold"])
      );
      
      const issuesSnapshot = await getDocs(issuesQuery);
      const issuesData = issuesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setIssues(issuesData);
    } catch (error) {
      console.error("Error fetching issues:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = async () => {
    if (!selectedIssue || !newStatus) {
      alert('Please select an issue and new status');
      return;
    }

    try {
      setUpdating(true);
      
      const issueRef = doc(db, "reports", selectedIssue.id);
      
      const updateData = {
        status: newStatus,
        statusUpdatedAt: new Date().toISOString(),
        statusUpdatedBy: 'department',
        statusNotes: statusNotes
      };

      // Add resolved date if status is resolved
      if (newStatus === 'resolved') {
        updateData.resolvedAt = new Date().toISOString();
      }

      await updateDoc(issueRef, updateData);

      // Add to audit trail
      await addDoc(collection(db, "auditTrail"), {
        issueId: selectedIssue.id,
        action: `Status Updated to ${newStatus}`,
        performedBy: 'department',
        performedAt: new Date().toISOString(),
        details: `Status changed to ${newStatus}. Notes: ${statusNotes}`,
        department: department
      });

      // Refresh data
      await fetchIssues();
      if (onStatsUpdate) onStatsUpdate();
      
      setSelectedIssue(null);
      setNewStatus('');
      setStatusNotes('');
      
      alert('Status updated successfully!');
      
    } catch (error) {
      console.error("Error updating status:", error);
      alert('Error updating status. Please try again.');
    } finally {
      setUpdating(false);
    }
  };

  const getStatusInfo = (status) => {
    return STATUS_OPTIONS.find(option => option.value === status) || STATUS_OPTIONS[0];
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="status-updates-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading status updates...</p>
      </div>
    );
  }

  return (
    <div className="status-updates">
      <div className="status-updates-header">
        <h2>📝 Status Updates</h2>
        <p>Update the status of assigned issues</p>
      </div>

      <div className="status-updates-content">
        <div className="issues-list">
          <h3>Active Issues ({issues.length})</h3>
          
          {issues.length === 0 ? (
            <div className="no-issues">
              <div className="no-issues-icon">📋</div>
              <h4>No active issues</h4>
              <p>No issues available for status updates.</p>
            </div>
          ) : (
            <div className="issues-grid">
              {issues.map(issue => (
                <div 
                  key={issue.id} 
                  className={`issue-card ${selectedIssue?.id === issue.id ? 'selected' : ''}`}
                  onClick={() => setSelectedIssue(issue)}
                >
                  <div className="issue-header">
                    <h4>{issue.title}</h4>
                    <span 
                      className="status-badge"
                      style={{ backgroundColor: getStatusInfo(issue.status).color }}
                    >
                      {getStatusInfo(issue.status).icon} {getStatusInfo(issue.status).label}
                    </span>
                  </div>
                  <p className="issue-description">{issue.description}</p>
                  <div className="issue-meta">
                    <span>📍 {issue.location}</span>
                    <span>📅 {formatDate(issue.createdAt)}</span>
                  </div>
                  {issue.assignedTo && (
                    <div className="assignment-info">
                      👤 Assigned to: {issue.assignedType === 'officer' ? 'Field Officer' : 'Contractor'}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {selectedIssue && (
          <div className="status-update-panel">
            <div className="status-update-header">
              <h3>Update Status</h3>
              <button 
                className="close-btn"
                onClick={() => {
                  setSelectedIssue(null);
                  setNewStatus('');
                  setStatusNotes('');
                }}
              >
                ✕
              </button>
            </div>

            <div className="issue-details">
              <h4>{selectedIssue.title}</h4>
              <p>{selectedIssue.description}</p>
              
              <div className="issue-info">
                <div className="info-item">
                  <span className="label">Current Status:</span>
                  <span 
                    className="value"
                    style={{ color: getStatusInfo(selectedIssue.status).color }}
                  >
                    {getStatusInfo(selectedIssue.status).icon} {getStatusInfo(selectedIssue.status).label}
                  </span>
                </div>
                <div className="info-item">
                  <span className="label">Location:</span>
                  <span className="value">{selectedIssue.location}</span>
                </div>
                <div className="info-item">
                  <span className="label">Priority:</span>
                  <span className="value">{selectedIssue.priority}</span>
                </div>
                {selectedIssue.assignedTo && (
                  <div className="info-item">
                    <span className="label">Assigned To:</span>
                    <span className="value">{selectedIssue.assignedTo}</span>
                  </div>
                )}
                <div className="info-item">
                  <span className="label">Last Updated:</span>
                  <span className="value">{formatDate(selectedIssue.statusUpdatedAt || selectedIssue.createdAt)}</span>
                </div>
              </div>
            </div>

            <div className="status-update-form">
              <div className="status-selection">
                <label htmlFor="newStatus">Select New Status</label>
                <select
                  id="newStatus"
                  value={newStatus}
                  onChange={(e) => setNewStatus(e.target.value)}
                  className="status-select"
                >
                  <option value="">Choose new status...</option>
                  {STATUS_OPTIONS.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.icon} {option.label}
                    </option>
                  ))}
                </select>
              </div>

              {newStatus && (
                <div className="status-preview">
                  <div className="preview-item">
                    <span className="preview-label">From:</span>
                    <span 
                      className="preview-value"
                      style={{ color: getStatusInfo(selectedIssue.status).color }}
                    >
                      {getStatusInfo(selectedIssue.status).icon} {getStatusInfo(selectedIssue.status).label}
                    </span>
                  </div>
                  <div className="preview-arrow">→</div>
                  <div className="preview-item">
                    <span className="preview-label">To:</span>
                    <span 
                      className="preview-value"
                      style={{ color: getStatusInfo(newStatus).color }}
                    >
                      {getStatusInfo(newStatus).icon} {getStatusInfo(newStatus).label}
                    </span>
                  </div>
                </div>
              )}

              <div className="status-notes">
                <label htmlFor="statusNotes">Status Update Notes</label>
                <textarea
                  id="statusNotes"
                  placeholder="Add notes about the status change (required for resolved/rejected statuses)..."
                  value={statusNotes}
                  onChange={(e) => setStatusNotes(e.target.value)}
                  className="notes-textarea"
                  rows="4"
                  required={newStatus === 'resolved' || newStatus === 'rejected'}
                />
              </div>

              <div className="status-actions">
                <button 
                  className="update-btn"
                  onClick={handleStatusUpdate}
                  disabled={updating || !newStatus || (newStatus === 'resolved' && !statusNotes.trim())}
                >
                  {updating ? '🔄 Updating...' : '✅ Update Status'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
