import React, { useState } from 'react';

export default function ReportCard({ 
  report, 
  onStatusUpdate, 
  onPriorityUpdate, 
  onAssign, 
  onViewDetails,
  getStatusColor,
  getPriorityColor 
}) {
  const [showActions, setShowActions] = useState(false);

  const formatDate = (date) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getCategoryIcon = (category) => {
    const icons = {
      'roads_transport': '🛣️',
      'water_sewage': '💧',
      'electricity': '⚡',
      'waste_management': '🗑️',
      'public_safety': '🚨',
      'parks_recreation': '🌳',
      'street_lighting': '🏮',
      'other': '📝'
    };
    return icons[category] || '📝';
  };

  const getStatusIcon = (status) => {
    const icons = {
      'submitted': '📝',
      'under_review': '👀',
      'assigned': '👥',
      'in_progress': '⚡',
      'resolved': '✅',
      'closed': '🔒',
      'rejected': '❌'
    };
    return icons[status] || '📝';
  };

  const getPriorityIcon = (priority) => {
    const icons = {
      'low': '🟢',
      'medium': '🟡',
      'high': '🟠',
      'critical': '🔴'
    };
    return icons[priority] || '🟡';
  };

  const truncateText = (text, maxLength = 100) => {
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength) + '...';
  };

  return (
    <div className="report-card" onMouseLeave={() => setShowActions(false)}>
      <div className="report-card-header">
        <div className="report-meta">
          <span className="report-id">#{report.id.slice(-6)}</span>
          <span className="report-date">{formatDate(report.createdAt)}</span>
        </div>
        <div className="report-actions">
          <button 
            className="actions-toggle"
            onClick={() => setShowActions(!showActions)}
          >
            ⋯
          </button>
          {showActions && (
            <div className="actions-dropdown">
              <button onClick={() => onViewDetails(report)}>
                👁️ View Details
              </button>
              <button onClick={() => onAssign()}>
                👥 Assign
              </button>
              <button onClick={() => onStatusUpdate(report.id, 'under_review')}>
                👀 Review
              </button>
              <button onClick={() => onStatusUpdate(report.id, 'resolved')}>
                ✅ Resolve
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="report-content">
        <div className="report-title-section">
          <span className="category-icon">{getCategoryIcon(report.category)}</span>
          <h3 className="report-title">{report.title}</h3>
        </div>

        <p className="report-description">
          {truncateText(report.description)}
        </p>

        <div className="report-location">
          📍 {report.address?.city}, {report.address?.state}
          {report.landmark && <span className="landmark"> • {report.landmark}</span>}
        </div>
      </div>

      <div className="report-status-row">
        <div className="status-badges">
          <span 
            className="status-badge"
            style={{ backgroundColor: getStatusColor(report.status) }}
          >
            {getStatusIcon(report.status)} {report.status.replace('_', ' ').toUpperCase()}
          </span>
          
          <span 
            className="priority-badge"
            style={{ backgroundColor: getPriorityColor(report.priority) }}
          >
            {getPriorityIcon(report.priority)} {report.priority.toUpperCase()}
          </span>
        </div>

        <div className="report-metrics">
          <span className="metric">
            👍 {report.votes?.upvotes || 0}
          </span>
          <span className="metric">
            👎 {report.votes?.downvotes || 0}
          </span>
          <span className="metric">
            👁️ {report.views || 0}
          </span>
        </div>
      </div>

      {report.assignedDepartment && (
        <div className="assignment-info">
          <span className="assigned-to">
            🏛️ {report.assignedDepartment}
            {report.assignedStaff && (
              <span className="staff-name"> • {report.assignedStaff}</span>
            )}
          </span>
        </div>
      )}

      <div className="report-media-indicator">
        {report.media && report.media.length > 0 && (
          <div className="media-count">
            📷 {report.media.length} attachment{report.media.length !== 1 ? 's' : ''}
          </div>
        )}
      </div>

      {report.lastUpdated && (
        <div className="last-updated">
          Last updated: {formatDate(report.lastUpdated)}
        </div>
      )}
    </div>
  );
}