import React, { useState, useEffect } from "react";
import { db } from "../../firebase/config.js";
import { collection, query, where, getDocs, doc, updateDoc, addDoc } from "firebase/firestore";
import "../../styles/department/ValidationPanel.css";

export default function ValidationPanel({ department, onStatsUpdate }) {
  const [pendingIssues, setPendingIssues] = useState([]);
  const [selectedIssue, setSelectedIssue] = useState(null);
  const [duplicateIssues, setDuplicateIssues] = useState([]);
  const [loading, setLoading] = useState(true);
  const [validating, setValidating] = useState(false);
  const [validationReason, setValidationReason] = useState('');
  const [aiAnalysis, setAiAnalysis] = useState(null);

  useEffect(() => {
    fetchPendingIssues();
  }, [department]);

  const fetchPendingIssues = async () => {
    try {
      setLoading(true);
      
      const issuesQuery = query(
        collection(db, "reports"),
        where("department", "==", department),
        where("status", "==", "pending")
      );
      
      const issuesSnapshot = await getDocs(issuesQuery);
      const issuesData = issuesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setPendingIssues(issuesData);
    } catch (error) {
      console.error("Error fetching pending issues:", error);
    } finally {
      setLoading(false);
    }
  };

  const analyzeIssue = async (issue) => {
    setSelectedIssue(issue);
    setAiAnalysis(null);
    
    // Simulate AI analysis for duplicate detection
    try {
      // Check for similar issues based on location and description
      const similarQuery = query(
        collection(db, "reports"),
        where("department", "==", department),
        where("status", "in", ["validated", "in-progress", "resolved"])
      );
      
      const similarSnapshot = await getDocs(similarQuery);
      const similarIssues = similarSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      // Simple similarity check (in real implementation, this would use ML)
      const duplicates = similarIssues.filter(similarIssue => {
        const locationMatch = similarIssue.location?.toLowerCase().includes(
          issue.location?.toLowerCase().split(' ')[0]
        );
        const descriptionMatch = calculateSimilarity(
          issue.description?.toLowerCase(),
          similarIssue.description?.toLowerCase()
        ) > 0.7;
        
        return locationMatch && descriptionMatch;
      });

      setDuplicateIssues(duplicates);

      // Generate AI analysis
      const analysis = {
        confidence: duplicates.length > 0 ? 0.8 : 0.9,
        isDuplicate: duplicates.length > 0,
        duplicateCount: duplicates.length,
        recommendations: generateRecommendations(issue, duplicates),
        riskScore: calculateRiskScore(issue),
        priority: calculatePriority(issue)
      };

      setAiAnalysis(analysis);
    } catch (error) {
      console.error("Error analyzing issue:", error);
    }
  };

  const calculateSimilarity = (str1, str2) => {
    if (!str1 || !str2) return 0;
    
    const words1 = str1.split(' ');
    const words2 = str2.split(' ');
    const commonWords = words1.filter(word => words2.includes(word));
    
    return commonWords.length / Math.max(words1.length, words2.length);
  };

  const generateRecommendations = (issue, duplicates) => {
    const recommendations = [];
    
    if (duplicates.length > 0) {
      recommendations.push({
        type: 'warning',
        message: `Potential duplicate detected. ${duplicates.length} similar issues found.`
      });
    }
    
    if (issue.priority === 'critical') {
      recommendations.push({
        type: 'urgent',
        message: 'High priority issue requires immediate attention.'
      });
    }
    
    if (!issue.images || issue.images.length === 0) {
      recommendations.push({
        type: 'info',
        message: 'No images provided. Consider requesting additional evidence.'
      });
    }
    
    return recommendations;
  };

  const calculateRiskScore = (issue) => {
    let score = 0;
    
    if (issue.priority === 'critical') score += 40;
    else if (issue.priority === 'high') score += 30;
    else if (issue.priority === 'medium') score += 20;
    else score += 10;
    
    if (issue.images && issue.images.length > 0) score += 20;
    if (issue.location && issue.location.length > 10) score += 20;
    if (issue.description && issue.description.length > 50) score += 20;
    
    return Math.min(score, 100);
  };

  const calculatePriority = (issue) => {
    if (issue.priority === 'critical') return 'critical';
    if (issue.priority === 'high') return 'high';
    if (issue.priority === 'medium') return 'medium';
    return 'low';
  };

  const handleValidation = async (issueId, action) => {
    try {
      setValidating(true);
      
      const issueRef = doc(db, "reports", issueId);
      const newStatus = action === 'accept' ? 'validated' : 'rejected';
      
      await updateDoc(issueRef, {
        status: newStatus,
        validatedAt: new Date().toISOString(),
        validatedBy: 'department',
        validationReason: validationReason || (action === 'accept' ? 'Issue validated by department' : 'Issue rejected by department')
      });

      // Add to audit trail
      await addDoc(collection(db, "auditTrail"), {
        issueId: issueId,
        action: `Issue ${action}ed`,
        performedBy: 'department',
        performedAt: new Date().toISOString(),
        details: validationReason || `Issue ${action}ed by department`,
        department: department
      });

      // Refresh data
      await fetchPendingIssues();
      if (onStatsUpdate) onStatsUpdate();
      
      setSelectedIssue(null);
      setValidationReason('');
      setAiAnalysis(null);
      setDuplicateIssues([]);
      
    } catch (error) {
      console.error("Error validating issue:", error);
    } finally {
      setValidating(false);
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="validation-loading">
        <div className="loading-spinner">🔄</div>
        <p>Loading validation panel...</p>
      </div>
    );
  }

  return (
    <div className="validation-panel">
      <div className="validation-header">
        <h2>✅ Issue Validation</h2>
        <p>Review and validate incoming issues with AI assistance</p>
      </div>

      <div className="validation-content">
        <div className="pending-issues">
          <h3>Pending Validation ({pendingIssues.length})</h3>
          
          {pendingIssues.length === 0 ? (
            <div className="no-pending">
              <div className="no-pending-icon">✅</div>
              <h4>All caught up!</h4>
              <p>No issues pending validation.</p>
            </div>
          ) : (
            <div className="issues-grid">
              {pendingIssues.map(issue => (
                <div 
                  key={issue.id} 
                  className={`issue-card ${selectedIssue?.id === issue.id ? 'selected' : ''}`}
                  onClick={() => analyzeIssue(issue)}
                >
                  <div className="issue-header">
                    <h4>{issue.title}</h4>
                    <span className="issue-priority">{issue.priority}</span>
                  </div>
                  <p className="issue-description">{issue.description}</p>
                  <div className="issue-meta">
                    <span>📍 {issue.location}</span>
                    <span>📅 {formatDate(issue.createdAt)}</span>
                  </div>
                  {issue.images && issue.images.length > 0 && (
                    <div className="issue-images">
                      📷 {issue.images.length} image(s)
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {selectedIssue && (
          <div className="validation-details">
            <div className="validation-details-header">
              <h3>Validation Details</h3>
              <button 
                className="close-btn"
                onClick={() => {
                  setSelectedIssue(null);
                  setAiAnalysis(null);
                  setDuplicateIssues([]);
                }}
              >
                ✕
              </button>
            </div>

            <div className="issue-details">
              <h4>{selectedIssue.title}</h4>
              <p>{selectedIssue.description}</p>
              
              <div className="issue-info">
                <div className="info-item">
                  <span className="label">Location:</span>
                  <span className="value">{selectedIssue.location}</span>
                </div>
                <div className="info-item">
                  <span className="label">Category:</span>
                  <span className="value">{selectedIssue.category}</span>
                </div>
                <div className="info-item">
                  <span className="label">Priority:</span>
                  <span className={`value priority-${selectedIssue.priority}`}>
                    {selectedIssue.priority}
                  </span>
                </div>
                <div className="info-item">
                  <span className="label">Reporter:</span>
                  <span className="value">{selectedIssue.reporterEmail}</span>
                </div>
                <div className="info-item">
                  <span className="label">Reported:</span>
                  <span className="value">{formatDate(selectedIssue.createdAt)}</span>
                </div>
              </div>
            </div>

            {aiAnalysis && (
              <div className="ai-analysis">
                <h4>🤖 AI Analysis</h4>
                
                <div className="analysis-summary">
                  <div className="analysis-item">
                    <span className="label">Confidence:</span>
                    <span className={`value confidence-${aiAnalysis.confidence > 0.8 ? 'high' : 'medium'}`}>
                      {Math.round(aiAnalysis.confidence * 100)}%
                    </span>
                  </div>
                  <div className="analysis-item">
                    <span className="label">Risk Score:</span>
                    <span className={`value risk-${aiAnalysis.riskScore > 70 ? 'high' : aiAnalysis.riskScore > 40 ? 'medium' : 'low'}`}>
                      {aiAnalysis.riskScore}/100
                    </span>
                  </div>
                  <div className="analysis-item">
                    <span className="label">Duplicates:</span>
                    <span className={`value ${aiAnalysis.isDuplicate ? 'duplicate-found' : 'no-duplicate'}`}>
                      {aiAnalysis.duplicateCount} found
                    </span>
                  </div>
                </div>

                {aiAnalysis.recommendations.length > 0 && (
                  <div className="recommendations">
                    <h5>Recommendations:</h5>
                    {aiAnalysis.recommendations.map((rec, index) => (
                      <div key={index} className={`recommendation ${rec.type}`}>
                        {rec.type === 'warning' && '⚠️ '}
                        {rec.type === 'urgent' && '🚨 '}
                        {rec.type === 'info' && 'ℹ️ '}
                        {rec.message}
                      </div>
                    ))}
                  </div>
                )}

                {duplicateIssues.length > 0 && (
                  <div className="duplicate-issues">
                    <h5>Similar Issues:</h5>
                    {duplicateIssues.map(dup => (
                      <div key={dup.id} className="duplicate-issue">
                        <div className="dup-title">{dup.title}</div>
                        <div className="dup-status">{dup.status}</div>
                        <div className="dup-date">{formatDate(dup.createdAt)}</div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="validation-actions">
              <textarea
                placeholder="Add validation reason (optional)..."
                value={validationReason}
                onChange={(e) => setValidationReason(e.target.value)}
                className="validation-reason"
                rows="3"
              />
              
              <div className="action-buttons">
                <button 
                  className="action-btn reject"
                  onClick={() => handleValidation(selectedIssue.id, 'reject')}
                  disabled={validating}
                >
                  {validating ? '🔄 Processing...' : '❌ Reject'}
                </button>
                <button 
                  className="action-btn accept"
                  onClick={() => handleValidation(selectedIssue.id, 'accept')}
                  disabled={validating}
                >
                  {validating ? '🔄 Processing...' : '✅ Accept'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
