import React, { useState } from 'react';

export default function ReportDetails({ 
  report, 
  onClose, 
  onStatusUpdate, 
  onPriorityUpdate, 
  onAssign 
}) {
  const [statusNotes, setStatusNotes] = useState('');
  const [showStatusUpdate, setShowStatusUpdate] = useState(false);

  const formatDate = (date) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const getCategoryIcon = (category) => {
    const icons = {
      'roads_transport': '🛣️',
      'water_sewage': '💧',
      'electricity': '⚡',
      'waste_management': '🗑️',
      'public_safety': '🚨',
      'parks_recreation': '🌳',
      'street_lighting': '🏮',
      'other': '📝'
    };
    return icons[category] || '📝';
  };

  const getStatusIcon = (status) => {
    const icons = {
      'submitted': '📝',
      'under_review': '👀',
      'assigned': '👥',
      'in_progress': '⚡',
      'resolved': '✅',
      'closed': '🔒',
      'rejected': '❌'
    };
    return icons[status] || '📝';
  };

  const getPriorityIcon = (priority) => {
    const icons = {
      'low': '🟢',
      'medium': '🟡',
      'high': '🟠',
      'critical': '🔴'
    };
    return icons[priority] || '🟡';
  };

  const handleStatusUpdateWithNotes = (newStatus) => {
    onStatusUpdate(report.id, newStatus, statusNotes);
    setStatusNotes('');
    setShowStatusUpdate(false);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="report-details-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Report Details</h2>
          <button className="close-btn" onClick={onClose}>✕</button>
        </div>

        <div className="modal-content">
          <div className="report-header-info">
            <div className="report-id-section">
              <h3>#{report.id.slice(-6)}</h3>
              <span className="creation-date">
                Created: {formatDate(report.createdAt)}
              </span>
            </div>

            <div className="status-priority-section">
              <div className="current-status">
                <span className="status-label">Status:</span>
                <span className="status-value">
                  {getStatusIcon(report.status)} {report.status.replace('_', ' ').toUpperCase()}
                </span>
              </div>
              <div className="current-priority">
                <span className="priority-label">Priority:</span>
                <span className="priority-value">
                  {getPriorityIcon(report.priority)} {report.priority.toUpperCase()}
                </span>
              </div>
            </div>
          </div>

          <div className="report-content-section">
            <div className="report-title">
              <span className="category-icon">{getCategoryIcon(report.category)}</span>
              <h3>{report.title}</h3>
            </div>

            <div className="report-description">
              <h4>Description:</h4>
              <p>{report.description}</p>
            </div>

            <div className="location-info">
              <h4>Location:</h4>
              <div className="address-details">
                <p>📍 {report.address?.street && `${report.address.street}, `}
                {report.address?.city}, {report.address?.state} {report.address?.zipCode}</p>
                {report.landmark && <p>🏛️ Near: {report.landmark}</p>}
                {report.location && (
                  <p>🗺️ Coordinates: {report.location.coordinates[1]}, {report.location.coordinates[0]}</p>
                )}
              </div>
            </div>

            {report.media && report.media.length > 0 && (
              <div className="media-section">
                <h4>Attachments ({report.media.length}):</h4>
                <div className="media-grid">
                  {report.media.map((media, index) => (
                    <div key={index} className="media-item">
                      <div className="media-info">
                        <span className="media-type">
                          {media.type === 'image' ? '📷' : '🎥'} {media.type}
                        </span>
                        <span className="media-size">
                          {(media.size / (1024 * 1024)).toFixed(2)} MB
                        </span>
                      </div>
                      <div className="media-filename">{media.filename}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="engagement-metrics">
              <h4>Community Engagement:</h4>
              <div className="metrics-row">
                <div className="metric">
                  <span className="metric-icon">👍</span>
                  <span className="metric-value">{report.votes?.upvotes || 0}</span>
                  <span className="metric-label">Upvotes</span>
                </div>
                <div className="metric">
                  <span className="metric-icon">👎</span>
                  <span className="metric-value">{report.votes?.downvotes || 0}</span>
                  <span className="metric-label">Downvotes</span>
                </div>
                <div className="metric">
                  <span className="metric-icon">👁️</span>
                  <span className="metric-value">{report.views || 0}</span>
                  <span className="metric-label">Views</span>
                </div>
              </div>
            </div>

            {report.assignedDepartment && (
              <div className="assignment-section">
                <h4>Assignment:</h4>
                <div className="assignment-details">
                  <p>🏛️ Department: {report.assignedDepartment}</p>
                  {report.assignedStaff && <p>👤 Staff: {report.assignedStaff}</p>}
                  {report.assignedAt && (
                    <p>📅 Assigned: {formatDate(report.assignedAt)}</p>
                  )}
                </div>
              </div>
            )}

            {report.statusHistory && report.statusHistory.length > 0 && (
              <div className="status-history">
                <h4>Status History:</h4>
                <div className="history-timeline">
                  {report.statusHistory.map((status, index) => (
                    <div key={index} className="history-item">
                      <div className="history-timestamp">
                        {formatDate(status.timestamp)}
                      </div>
                      <div className="history-status">
                        {getStatusIcon(status.status)} {status.status.replace('_', ' ')}
                      </div>
                      {status.notes && (
                        <div className="history-notes">{status.notes}</div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="modal-actions">
          <div className="action-buttons-left">
            <button 
              className="priority-btn low"
              onClick={() => onPriorityUpdate(report.id, 'low')}
            >
              🟢 Set Low Priority
            </button>
            <button 
              className="priority-btn medium"
              onClick={() => onPriorityUpdate(report.id, 'medium')}
            >
              🟡 Set Medium Priority
            </button>
            <button 
              className="priority-btn high"
              onClick={() => onPriorityUpdate(report.id, 'high')}
            >
              🟠 Set High Priority
            </button>
            <button 
              className="priority-btn critical"
              onClick={() => onPriorityUpdate(report.id, 'critical')}
            >
              🔴 Set Critical
            </button>
          </div>

          <div className="action-buttons-right">
            <button 
              className="assign-btn"
              onClick={onAssign}
            >
              👥 Assign Report
            </button>
            
            <button 
              className="status-update-btn"
              onClick={() => setShowStatusUpdate(!showStatusUpdate)}
            >
              📝 Update Status
            </button>
          </div>
        </div>

        {showStatusUpdate && (
          <div className="status-update-section">
            <h4>Update Status:</h4>
            <textarea
              placeholder="Add notes about status update (optional)..."
              value={statusNotes}
              onChange={(e) => setStatusNotes(e.target.value)}
              rows={3}
            />
            <div className="status-buttons">
              <button onClick={() => handleStatusUpdateWithNotes('under_review')}>
                👀 Under Review
              </button>
              <button onClick={() => handleStatusUpdateWithNotes('in_progress')}>
                ⚡ In Progress
              </button>
              <button onClick={() => handleStatusUpdateWithNotes('resolved')}>
                ✅ Resolved
              </button>
              <button onClick={() => handleStatusUpdateWithNotes('closed')}>
                🔒 Close
              </button>
              <button onClick={() => handleStatusUpdateWithNotes('rejected')}>
                ❌ Reject
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}