import React, { useState } from 'react';

export default function StaffCard({ staff, onAction, onViewDetails }) {
  const [showActions, setShowActions] = useState(false);

  const formatDate = (date) => {
    if (!date) return 'N/A';
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const getStatusColor = (status) => {
    const colors = {
      'active': '#10b981',
      'suspended': '#f59e0b',
      'banned': '#ef4444',
      'pending': '#6b7280'
    };
    return colors[status] || '#6b7280';
  };

  const getStatusIcon = (status) => {
    const icons = {
      'active': '✅',
      'suspended': '⏸️',
      'banned': '🚫',
      'pending': '⏳'
    };
    return icons[status] || '❓';
  };

  const getDepartmentIcon = (department) => {
    const icons = {
      'Public Works': '🏗️',
      'Water Authority': '💧',
      'Electric Board': '⚡',
      'Sanitation Department': '🗑️',
      'Police Department': '🚨',
      'Parks & Recreation': '🌳',
      'Transportation': '🚌'
    };
    return icons[department] || '🏛️';
  };

  const handleAction = (action) => {
    if (action === 'suspend' || action === 'ban') {
      const reason = prompt(`Please provide a reason for ${action}ing this staff member:`);
      if (reason) {
        onAction(staff.id, action, { reason, status: action === 'suspend' ? 'suspended' : 'banned' });
      }
    } else {
      onAction(staff.id, action);
    }
    setShowActions(false);
  };

  return (
    <div className="staff-card" onMouseLeave={() => setShowActions(false)}>
      <div className="staff-card-header">
        <div className="staff-avatar">
          {staff.photoURL ? (
            <img src={staff.photoURL} alt={staff.displayName} />
          ) : (
            <div className="avatar-placeholder">
              {(staff.displayName || staff.email || 'S').charAt(0).toUpperCase()}
            </div>
          )}
        </div>
        
        <div className="staff-basic-info">
          <h3 className="staff-name">{staff.displayName || 'Unknown Staff'}</h3>
          <p className="staff-email">{staff.email}</p>
          {staff.department && (
            <p className="staff-department">
              {getDepartmentIcon(staff.department)} {staff.department}
            </p>
          )}
        </div>

        <div className="staff-actions">
          <button 
            className="actions-toggle"
            onClick={() => setShowActions(!showActions)}
          >
            ⋯
          </button>
          {showActions && (
            <div className="actions-dropdown">
              <button onClick={() => onViewDetails(staff)}>
                👁️ View Details
              </button>
              {staff.status === 'pending' && (
                <button onClick={() => handleAction('approve')}>
                  ✅ Approve
                </button>
              )}
              {staff.status === 'active' && (
                <>
                  <button onClick={() => handleAction('suspend')}>
                    ⏸️ Suspend
                  </button>
                  <button onClick={() => handleAction('ban')}>
                    🚫 Remove
                  </button>
                </>
              )}
              {(staff.status === 'suspended' || staff.status === 'banned') && (
                <button onClick={() => handleAction('unban')}>
                  ✅ Restore
                </button>
              )}
              <button onClick={() => handleAction('delete')} className="danger">
                🗑️ Delete
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="staff-details">
        {staff.position && (
          <div className="detail-item">
            <span className="detail-label">Position:</span>
            <span className="detail-value">{staff.position}</span>
          </div>
        )}
        
        <div className="detail-item">
          <span className="detail-label">Workload:</span>
          <span className="detail-value">{staff.currentWorkload || 0} reports</span>
        </div>
        
        <div className="detail-item">
          <span className="detail-label">Joined:</span>
          <span className="detail-value">{formatDate(staff.createdAt)}</span>
        </div>
      </div>

      <div className="staff-status">
        <span 
          className="status-badge"
          style={{ backgroundColor: getStatusColor(staff.status || 'pending') }}
        >
          {getStatusIcon(staff.status || 'pending')} {(staff.status || 'pending').toUpperCase()}
        </span>
      </div>

      <div className="staff-stats">
        <div className="stat-item">
          <span className="stat-label">Resolved</span>
          <span className="stat-value">{staff.reportsResolved || 0}</span>
        </div>
        
        <div className="stat-item">
          <span className="stat-label">Response Time</span>
          <span className="stat-value">{staff.avgResponseTime || 'N/A'}</span>
        </div>
      </div>

      {staff.lastActive && (
        <div className="last-active">
          Last active: {formatDate(staff.lastActive)}
        </div>
      )}

      {(staff.suspensionReason || staff.banReason) && (
        <div className="action-reason">
          <strong>Reason:</strong> {staff.suspensionReason || staff.banReason}
        </div>
      )}
    </div>
  );
}